/* Généré par tools/ck_build.py depuis data/ck/ : ne pas modifier à la main. */
window.CK_HYP={"acidocetose-diabetique":{"bloquant":true,"confirmation":"L’acidocétose diabétique se confirme par une glycémie supérieure à 13,9 millimoles par litre, des corps cétoniques dans le sang ou dans l’urine, et une acidose : pH artériel inférieur à 7,35 ou pH veineux inférieur à 7,3, bicarbonate inférieur à 15 millimoles par litre. Elle peut aussi survenir avec une glycémie presque normale, par exemple sous inhibiteur du SGLT2.","exam":{"lignes":[{"mecanisme":"Le manque d’insuline empêche les cellules d’utiliser le glucose et libère les acides gras, que le foie transforme en corps cétoniques acides.","nom":"Glycémie et corps cétoniques dans le sang ou dans l’urine","pourquoi_ce_choix":"La ligne directrice demande d’emblée la glycémie et les corps cétoniques ; s’ils sont anormaux, le bilan se complète aussitôt par un gaz du sang.","principe":"On mesure la glycémie et les corps cétoniques dans le sang capillaire ou dans l’urine.","rang":1,"recherche":"Il recherche une glycémie supérieure à 13,9 millimoles par litre et des corps cétoniques dans le sang ou dans l’urine.","src":[{"id":"R-DDG-T1","loc":"§ 9.2.2 et 9.2.4","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les corps cétoniques consomment le bicarbonate du sang et provoquent une acidose métabolique.","nom":"Gaz du sang, potassium, créatinine, numération et protéine C réactive","pourquoi_ce_choix":"Ces valeurs confirment l’acidose, classent la gravité (pH inférieur à 7,3, à 7,2 ou à 7,1) et guident le traitement, surtout le potassium.","principe":"Le gaz du sang artériel ou veineux mesure le pH et le bicarbonate ; la prise de sang ajoute le potassium, la créatinine, la numération et la protéine C réactive.","rang":2,"recherche":"Il recherche l’acidose métabolique, sa gravité et le niveau du potassium.","src":[{"id":"R-DDG-T1","loc":"§ 9.2.4 ; Tabelle 22","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une infection, un infarctus du myocarde, un accident vasculaire cérébral ou un arrêt de l’insuline déclenchent souvent l’acidocétose.","nom":"Recherche de la cause : cultures et examens orientés par la clinique","pourquoi_ce_choix":"Le traitement de la cause fait partie de la prise en charge, et la maladie déclenchante peut dominer le tableau clinique.","principe":"On prélève des cultures (sang, urine, gorge) si une infection est suspecte, puis on complète le bilan selon les maladies associées.","rang":3,"recherche":"Ils recherchent une infection, une ischémie ou un autre facteur déclenchant.","src":[{"id":"R-DDG-T1","loc":"§ 9.2.3 et 9.2.4 ; Empfehlung 9-7","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"acidocetose-diabetique","label":"Acidocétose diabétique","pec":{"mesures_generales":["L’équipe de diabétologie participe à la prise en charge dès que possible.","La glycémie et les corps cétoniques se contrôlent chaque heure, et le gaz du sang veineux avec le potassium à 60 minutes, à 2 heures, puis toutes les 2 heures.","La cause déclenchante se recherche et se traite en même temps."],"moyens_specifiques":[{"dose_ref":null,"limites":"Le volume s’adapte aux maladies associées, comme une insuffisance cardiaque ou rénale ; une baisse trop rapide de la glycémie expose à l’œdème cérébral.","mecanisme":"Le glucose qui passe dans l’urine entraîne une diurèse osmotique qui déshydrate le patient et peut gêner la microcirculation.","pourquoi_ce_choix":"La ligne directrice place la stabilisation circulatoire en tête des principes du traitement, avant la baisse de la glycémie.","principe":"On rétablit le volume circulant et la perfusion des organes par une perfusion intraveineuse de solution électrolytique.","src":[{"id":"R-DDG-T1","loc":"Empfehlung 9-7 ; Tabelle 21","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une solution électrolytique balancée se perfuse dès la première heure pour stabiliser la circulation, puis le remplissage se poursuit selon l’âge, le poids et les maladies associées ; les volumes et les débits restent À vérifier.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle expose à l’hypoglycémie et à l’hypokaliémie, ce qui impose une surveillance au moins horaire ; la glycémie ne descend pas sous 13,9 millimoles par litre pendant les 24 premières heures, surtout dans une acidocétose sévère.","mecanisme":"Sans insuline, l’organisme brûle les graisses et le foie fabrique des corps cétoniques acides.","pourquoi_ce_choix":"Des essais ont montré l’avantage de la faible dose sur la forte dose, et la baisse lente de la glycémie protège du œdème cérébral.","principe":"On arrête la production de corps cétoniques par une perfusion intraveineuse continue d’insuline à faible dose.","src":[{"id":"R-DDG-T1","loc":"Empfehlung 9-6 et 9-7 ; § 9.2.6","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’insuline à faible dose se perfuse par voie intraveineuse au pousse-seringue ; elle ne s’interrompt pas avant un pH de 7,3, et du glucose s’ajoute à la perfusion quand la glycémie descend, pour éviter une baisse trop rapide. Le débit reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"La kaliémie peut chuter très vite sous insuline ; la perfusion d’insuline s’arrête alors jusqu’à ce que le potassium revienne dans la norme.","mecanisme":"L’insuline fait entrer le potassium dans les cellules, alors que la diurèse osmotique a déjà vidé les réserves de l’organisme.","pourquoi_ce_choix":"Il prévient l’hypokaliémie provoquée par l’insuline, qui expose aux arythmies cardiaques.","principe":"On compense ces pertes en ajoutant du chlorure de potassium aux perfusions selon la kaliémie mesurée.","src":[{"id":"R-DDG-T1","loc":"Empfehlung 9-7 ; Kaliumgabe","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le potassium s’ajoute à la perfusion dès que la kaliémie est normale ou basse, et pas au-dessus de 5,5 millimoles par litre ; si elle est basse, le potassium se donne avant l’insuline. Les quantités restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à restaurer la volémie, à arrêter la production de corps cétoniques et à corriger les troubles électrolytiques sans provoquer de complication."},"src":[{"id":"R-DDG-T1","loc":"§ 9.2 Diabetische Ketoazidose","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-kussmaul"]},"anaphylaxie":{"bloquant":true,"confirmation":"Le diagnostic repose sur les critères cliniques ; une tryptase élevée le soutient a posteriori, et le bilan allergologique recherche ensuite le déclencheur.","exam":{"lignes":[{"mecanisme":"Un allergène, souvent par un mécanisme lié aux IgE, active brutalement les mastocytes et les basophiles, qui libèrent de l’histamine et d’autres médiateurs dans tout l’organisme.","nom":"Diagnostic clinique selon les critères de l’EAACI","pourquoi_ce_choix":"Le diagnostic est clinique et immédiat, car l’adrénaline ne doit attendre aucun résultat de laboratoire.","precautions":"Chez l’adulte, une pression systolique inférieure à 90 mmHg, ou une baisse de plus de 30 % par rapport à sa valeur habituelle, après exposition à un allergène connu suffit au diagnostic.","principe":"Les critères reconnaissent l’anaphylaxie devant une atteinte brutale de la peau ou des muqueuses avec une atteinte respiratoire ou une baisse de la pression, devant deux atteintes après exposition à un allergène probable, ou devant une hypotension après exposition à un allergène connu.","rang":1,"recherche":"Il recherche l’urticaire ou l’angio-œdème, la dyspnée, le stridor ou les sibilants, l’hypotension et des troubles digestifs persistants.","src":[{"id":"R-EAACI-ANA","loc":"Box 1, Clinical criteria for diagnosing anaphylaxis","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les mastocytes activés libèrent de la tryptase, qui reste élevée quelques heures dans le sang.","nom":"Dosage de la tryptase sérique, à distance du traitement","pourquoi_ce_choix":"Il ne guide pas le traitement immédiat mais soutient plus tard le diagnostic et le bilan allergologique ; une valeur supérieure à 1,2 fois la valeur de base plus 2 microgrammes par litre soutient le diagnostic.","precautions":"Une tryptase normale n’exclut pas l’anaphylaxie, surtout chez l’enfant et lors d’une allergie alimentaire.","principe":"Un dosage fait entre 30 minutes et 2 heures après le début, comparé à un dosage de base fait au moins 24 heures après la guérison, documente l’activation des mastocytes.","rang":2,"recherche":"Il recherche une élévation transitoire de la tryptase sérique.","src":[{"id":"R-EAACI-ANA","loc":"Diagnosis, recommandation sur la tryptase","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"anaphylaxie","label":"Anaphylaxie","pec":{"mesures_generales":["L’équipe demande de l’aide tôt et injecte l’adrénaline sans attendre.","Le patient reste surveillé 6 à 8 heures après une atteinte respiratoire, et au moins 12 à 24 heures après une hypotension, à cause du risque de réaction prolongée ou biphasique.","Avant sa sortie, le patient à risque de récidive reçoit un auto-injecteur d’adrénaline, une instruction écrite et un rendez-vous chez un allergologue."],"moyens_specifiques":[{"dose_ref":null,"limites":"Elle peut échouer en cas de détresse respiratoire réfractaire ou d’hypotension : l’adrénaline intraveineuse se réserve alors à une équipe formée en milieu surveillé. Un patient sous bêtabloquant peut mal y répondre.","mecanisme":"Les médiateurs des mastocytes dilatent les vaisseaux, rendent les capillaires perméables et contractent les bronches.","pourquoi_ce_choix":"La voie intramusculaire à la cuisse donne des taux plasmatiques plus élevés que la voie sous-cutanée, l’inhalation ou l’injection dans le deltoïde, avec peu d’effets graves, contrairement à la voie intraveineuse ; son emploi précoce semble réduire les réactions biphasiques.","principe":"L’adrénaline contre ces effets : elle resserre les vaisseaux, renforce la contraction du cœur et dilate les bronches.","src":[{"id":"R-EAACI-ANA","loc":"Management, First line intervention: adrenaline, Route of administration","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’adrénaline intramusculaire, injectée sans délai au milieu de la cuisse, est le traitement de première ligne, et elle se répète si la réponse manque. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Le remplissage ne remplace jamais l’adrénaline, et ses volumes chez l’insuffisant cardiaque restent À vérifier.","mecanisme":"La fuite capillaire et la vasodilatation vident le compartiment vasculaire du patient en choc anaphylactique.","pourquoi_ce_choix":"L’adrénaline peut rester inefficace tant que le volume circulant n’est pas restauré, ce qui justifie un remplissage précoce.","principe":"On restaure le volume circulant par des bolus intraveineux de cristalloïdes.","src":[{"id":"R-EAACI-ANA","loc":"Management, intravenous fluids","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le patient avec atteinte cardiovasculaire reçoit des cristalloïdes intraveineux dès la première injection d’adrénaline, en bolus répétés selon la réponse ; les volumes restent À vérifier.","type":"pharmaco"},{"dose_ref":null,"limites":"L’adrénaline inhalée passe très peu dans le sang et ne remplace jamais l’injection intramusculaire ; les glucocorticoïdes pourraient être délétères chez l’enfant.","mecanisme":"Le bronchospasme et l’œdème du larynx peuvent persister malgré l’adrénaline intramusculaire.","pourquoi_ce_choix":"Ces traitements agissent sur place là où l’obstruction persiste ; les antihistaminiques soulagent seulement les signes cutanés, et l’effet des glucocorticoïdes reste mal prouvé.","principe":"On ajoute un bronchodilatateur inhalé, ou de l’adrénaline nébulisée, qui agit au contact de la zone atteinte.","src":[{"id":"R-EAACI-ANA","loc":"Management, Inhaled Beta2-Agonists, Inhaled adrenaline, H1 and H2 antihistamines, Glucocorticoids","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le salbutamol inhalé s’ajoute si l’obstruction bronchique domine, et l’adrénaline nébulisée avec de l’oxygène si un œdème du larynx ou du pharynx est suspecté ; les antihistaminiques et les glucocorticoïdes ne viennent qu’en second. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à contrer immédiatement les effets des médiateurs sur les voies aériennes et la circulation, puis à prévenir une récidive."},"src":[{"id":"R-EAACI-ANA","loc":"Recommendations, Table 2 ; Management","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-reaction-allergique","urg-choc"]},"asthme-aigu-grave":{"bloquant":true,"confirmation":"La crise d’asthme grave se confirme sur la clinique, la saturation et le débit de pointe ; les gaz du sang mesurent la menace ventilatoire.","exam":{"lignes":[{"mecanisme":"Le bronchospasme, l’œdème et le mucus réduisent le calibre des bronches ; le patient s’épuise à expirer, puis il ne ventile plus assez.","nom":"Signes de gravité, fréquences, saturation et débit expiratoire de pointe","pourquoi_ce_choix":"La ligne directrice définit la crise grave par une dyspnée à la parole, une fréquence respiratoire d’au moins 25 par minute, une fréquence cardiaque d’au moins 110 par minute, une saturation inférieure à 92 % ou un débit de pointe inférieur à 50 % de la meilleure valeur personnelle.","precautions":"Un thorax silencieux ne signe pas une amélioration : il traduit un débit d’air si faible que les sibilants disparaissent.","principe":"On compte la fréquence respiratoire et la fréquence cardiaque, on mesure la saturation, on note la dyspnée à la parole et on mesure le débit expiratoire de pointe si le patient y parvient.","rang":1,"recherche":"Il recherche les signes de crise grave, puis les signes de menace vitale : silence auscultatoire, respiration superficielle, cyanose, bradycardie, hypotension, épuisement, confusion ou débit de pointe inférieur à 33 %.","src":[{"id":"R-NVL-ASTHME","loc":"chapitre 7, Abbildung 7 (Asthmaanfall bei Erwachsenen)","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Au début de la crise, l’hyperventilation abaisse le gaz carbonique ; une pression partielle normale ou élevée signale que le patient s’épuise.","nom":"Gaz du sang artériel","pourquoi_ce_choix":"La ligne directrice retient une pression de gaz carbonique normale ou élevée comme signe de menace vitale, et un pH inférieur à 7,35 comme critère d’admission aux soins intensifs.","principe":"Le prélèvement artériel mesure l’oxygène, le gaz carbonique et le pH du sang.","rang":2,"recherche":"Il recherche une hypoxémie, une hypercapnie et une acidose respiratoire.","src":[{"id":"R-NVL-ASTHME","loc":"chapitre 7, Abbildung 7 et 8 ; diagnostic de la crise","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"La réponse aux bronchodilatateurs sépare la crise qui se lève de la crise réfractaire, qui menace la vie.","nom":"Réévaluation de la réponse 30 à 60 minutes après le début du traitement","pourquoi_ce_choix":"La ligne directrice fixe cette réévaluation pour décider du retour à domicile, de l’hospitalisation ou de l’admission aux soins intensifs.","principe":"On répète l’examen, la saturation et le débit de pointe après les premières inhalations.","rang":3,"recherche":"Il recherche la persistance des signes de gravité, un épuisement, une confusion ou une baisse de la saturation.","src":[{"id":"R-NVL-ASTHME","loc":"chapitre 7, Abbildung 8","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"asthme-aigu-grave","label":"Asthme aigu grave","pec":{"mesures_generales":["Le patient reste assis, sous surveillance continue de la saturation, avec un oxygène réglé pour viser une saturation de 92 à 96 %.","Le patient qui risque une hypercapnie reçoit un oxygène réglé pour viser une saturation de 88 à 92 %.","L’équipe appelle les soins intensifs devant une saturation inférieure à 92 % malgré l’oxygène, un pH inférieur à 7,35, un débit de pointe inférieur à 40 %, un épuisement, une confusion ou un coma."],"moyens_specifiques":[{"dose_ref":null,"limites":"Il provoque une tachycardie et un tremblement ; il ne traite pas l’inflammation, qui entretient la crise pendant des jours.","mecanisme":"La contraction du muscle lisse bronchique rétrécit les bronches et bloque l’expiration.","pourquoi_ce_choix":"Il agit le plus vite sur le bronchospasme, et la ligne directrice en fait le premier traitement de toute crise.","principe":"Un bêta-2 mimétique de courte durée d’action relâche le muscle lisse bronchique en quelques minutes.","src":[{"id":"R-NVL-ASTHME","loc":"chapitre 7, Abbildung 8","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le bêta-2 mimétique de courte durée d’action s’inhale par un aérosol doseur avec une chambre d’inhalation, et l’inhalation se répète après 10 à 15 minutes si besoin ; l’ipratropium s’y ajoute dans la crise grave. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Son effet demande plusieurs heures ; il ne remplace jamais le bronchodilatateur.","mecanisme":"L’inflammation de la paroi bronchique entretient l’œdème, le mucus et l’hyperréactivité des bronches.","pourquoi_ce_choix":"La ligne directrice le recommande dès le début de toute crise grave, et son action sur l’inflammation complète celle du bronchodilatateur.","principe":"Un corticoïde systémique réduit cette inflammation en quelques heures et prévient la rechute précoce.","src":[{"id":"R-NVL-ASTHME","loc":"chapitre 7, Abbildung 8","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un corticoïde systémique se donne dès le début de toute crise grave, par voie orale si le patient avale. Les doses de la figure de la ligne directrice relèvent d’un consensus d’experts ; les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Ils exigent une surveillance continue ; l’intubation d’un asthmatique grave expose à des complications et demande une équipe expérimentée.","mecanisme":"Une crise réfractaire aux inhalations garde un bronchospasme qui épuise le patient.","pourquoi_ce_choix":"La ligne directrice les place comme options supplémentaires après l’échec du traitement initial.","principe":"Le sulfate de magnésium intraveineux et un bêta-2 mimétique parentéral relâchent le muscle bronchique par d’autres voies.","src":[{"id":"R-NVL-ASTHME","loc":"chapitre 7, Abbildung 8, weitere Therapieoptionen","lu_le":"2026-10-17"}],"statut":"À vérifier","texte":"Le sulfate de magnésium intraveineux ou un bêta-2 mimétique par voie parentérale s’envisagent en cas de crise réfractaire ; une ventilation se discute aux soins intensifs. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à lever le bronchospasme, à corriger l’hypoxémie et à repérer à temps le patient qui doit aller aux soins intensifs."},"src":[{"id":"R-NVL-ASTHME","loc":"chapitre 7, Asthmaanfall bei Erwachsenen","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-dyspnee-sifflante"]},"avc-hemorragique":{"bloquant":true,"confirmation":"Le diagnostic est posé par l’imagerie cérébrale, qui montre l’hématome dans le tissu cérébral.","exam":{"lignes":[{"mecanisme":"Une artère rompue saigne dans le cerveau, et l’hématome peut grossir dans les premières heures.","nom":"Scanner cérébral sans injection en urgence","pourquoi_ce_choix":"Il est rapide et distingue l’hémorragie de l’ischémie, ce qui décide de tout le traitement : une thrombolyse est exclue.","precautions":"L’équipe recherche d’emblée un traitement anticoagulant, car sa neutralisation est urgente.","principe":"Le scanner sans injection montre l’hématome, son siège, son volume et une extension dans les ventricules.","rang":1,"recherche":"Il montre l’hématome, son siège, son volume et une extension dans les ventricules.","src":[{"id":"R-ESO-ICH","loc":"PICO 1.2.1, Additional information","lu_le":"2026-10-17"},{"id":"R-ESO-IVT","loc":"Recommandations < 4,5 h","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Une angiographie normale au scanner n’exclut pas une malformation ; l’artériographie numérisée reste l’examen de référence.","mecanisme":"Chez le sujet jeune, un hématome lobaire ou cérébelleux sans hypertension connue peut venir d’une anomalie des vaisseaux.","nom":"Angioscanner, IRM ou angio-IRM","pourquoi_ce_choix":"Ces examens se font sans cathétérisme et en urgence, ce qui les place avant l’artériographie.","principe":"L’imagerie vasculaire montre une malformation artérioveineuse, un anévrisme, une fistule durale, une malformation caverneuse ou une thrombose veineuse.","rang":2,"recherche":"Elle recherche une cause macrovasculaire.","src":[{"id":"R-ESO-ICH","loc":"PICO 1.2.1 et 1.2.2","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une petite malformation vasculaire peut échapper à l’angioscanner.","nom":"Artériographie numérisée par cathétérisme","pourquoi_ce_choix":"C’est l’examen de référence des malformations ; on le garde pour une suspicion qui persiste malgré un angioscanner normal.","precautions":"Elle est invasive, avec environ 0,6 % de complications ; l’indication se décide au cas par cas.","principe":"Un cathéter injecte le produit de contraste directement dans les artères, ce qui donne une image plus fine.","rang":3,"recherche":"Elle recherche une malformation vasculaire que l’angioscanner n’a pas montrée.","src":[{"id":"R-ESO-ICH","loc":"PICO 1.2.2","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"avc-hemorragique","label":"Hémorragie intracérébrale spontanée","pec":{"mesures_generales":["Le patient est admis dans une unité de l’AVC organisée, sauf s’il relève des soins intensifs.","Un avis neurochirurgical est demandé tôt en cas d’hématome volumineux, d’hémorragie dans les ventricules ou d’hématome compressif de la fosse postérieure.","Un dépistage des troubles de la déglutition est fait, et aucune décision de non-réanimation n’est prise dans les 24 premières heures sauf volonté claire du patient."],"moyens_specifiques":[{"limites":"La baisse ne dépasse pas 70 mmHg et la pression ne descend pas sous 110 mmHg ; la recommandation ne porte pas sur les hématomes plus volumineux.","mecanisme":"Une pression artérielle élevée s’associe à l’expansion de l’hématome, au décès et à la dépendance.","pourquoi_ce_choix":"Cette mesure ne demande ni geste invasif ni centre spécialisé, et la ligne directrice la propose pour les hématomes de petit ou moyen volume.","principe":"Abaisser tôt la pression vise à prévenir l’expansion de l’hématome et l’aggravation clinique.","src":[{"id":"R-ESO-ICH","loc":"Blood pressure management ; PICO 2, Expert consensus statements","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La pression systolique est abaissée sous 140 mmHg dans les 6 heures pour un hématome de moins de 30 millilitres. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Le niveau de preuve reste faible ou très faible pour les antidotes, et le risque d’événements thromboemboliques doit être pesé.","mecanisme":"Sous anticoagulant, la coagulation est diminuée, et l’hématome risque davantage de grossir.","pourquoi_ce_choix":"Le moyen dépend de la molécule : concentré de complexe prothrombinique avec vitamine K intraveineuse sous antivitamine K, idarucizumab sous dabigatran, andexanet alfa ou concentré de complexe prothrombinique sous inhibiteur du facteur Xa.","principe":"On rétablit la coagulation en neutralisant l’anticoagulant le plus vite possible.","src":[{"id":"R-ESO-ICH","loc":"PICO 3.3.1 à 3.3.2.2","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’anticoagulant est neutralisé en urgence par un moyen adapté à la molécule. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Le bénéfice n’est pas uniforme, et la décision reste individuelle après un avis neurochirurgical.","mecanisme":"L’hématome comprime le cerveau, et ses produits de dégradation déclenchent une inflammation qui ajoute une lésion secondaire.","pourquoi_ce_choix":"Elle n’est proposée que si le siège, le volume, l’état neurologique, le délai et l’expérience de l’équipe la rendent favorable, car les essais donnent des résultats différents selon ces facteurs.","principe":"On retire l’hématome pour lever la compression et limiter la lésion secondaire.","src":[{"id":"R-ESO-ICH","loc":"PICO 4.1 ; Surgery, Analysis of current evidence","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une évacuation chirurgicale d’un hématome supratentoriel peut être proposée.","type":"chirurgie"}],"objectif":"Le traitement vise à limiter l’expansion de l’hématome et les complications pour réduire le décès et la dépendance."},"src":[{"id":"R-ESO-ICH","loc":"Abstract ; PICO 1 à 5","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site1-central"]},"avc-ischemique":{"bloquant":true,"confirmation":"Le diagnostic repose sur un déficit neurologique focal brutal avec une imagerie qui exclut une hémorragie ; l’IRM de diffusion montre l’infarctus.","exam":{"lignes":[{"alternative":"Lors d’un AVC constaté au réveil, une IRM qui montre un décalage diffusion-FLAIR permet encore la thrombolyse si une thrombectomie n’est pas prévue.","mecanisme":"Un caillot bouche une artère du cerveau ; autour du cœur de l’infarctus, une zone mal perfusée reste récupérable pendant quelques heures.","nom":"Imagerie cérébrale en urgence (scanner sans injection ou IRM)","pourquoi_ce_choix":"Le bénéfice de la reperfusion baisse avec le temps : l’examen le plus rapide qui exclut une hémorragie passe donc en premier. L’IRM convient aussi si elle ne retarde pas le traitement.","precautions":"Sous antivitamine K, la thrombolyse n’est faite que si l’INR est connu et ne dépasse pas 1,7 ; après un anticoagulant oral direct pris dans les 48 heures, elle exige un dosage spécifique.","principe":"Le scanner sans injection montre une hémorragie, qui interdit la thrombolyse, et l’étendue des signes précoces d’ischémie.","rang":1,"recherche":"Elle recherche une hémorragie et l’étendue des signes précoces d’ischémie.","src":[{"id":"R-ESO-IVT","loc":"Recommandations < 4,5 h ; 4,5 à 9 h ; AVC grave (ASPECTS)","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Quand le caillot bouche une grosse artère de la circulation antérieure, il menace un vaste territoire et peut être retiré mécaniquement.","nom":"Angioscanner ou angio-IRM des vaisseaux cervicaux et intracrâniens","pourquoi_ce_choix":"Elle seule désigne les patients qui gagnent à une thrombectomie : celle-ci améliore le pronostic jusqu’à 6 heures, et entre 6 et 24 heures si les critères des essais sont remplis.","precautions":"Les précautions du produit de contraste (fonction rénale, allergie) restent À vérifier dans une source suisse ou européenne.","principe":"L’injection opacifie les artères et montre l’endroit où le flux s’arrête.","rang":2,"recherche":"Elle recherche l’occlusion d’une grosse artère de la circulation antérieure.","src":[{"id":"R-ESO-MT","loc":"PICO 1 et 2","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Le délai seul ne dit pas si le tissu est perdu : chez certains patients, une zone récupérable persiste au-delà de 4,5 heures.","nom":"Imagerie de perfusion (scanner ou IRM)","pourquoi_ce_choix":"Elle ne sert qu’au-delà de 4,5 heures ou si l’heure de début est inconnue, car le scanner sans injection ne montre pas ce tissu récupérable ; dans les 4,5 heures, elle ne doit pas retarder la thrombolyse.","principe":"Elle compare le cœur de l’infarctus et la zone mal perfusée ; leur décalage quantifie le tissu encore récupérable.","rang":3,"recherche":"Elle mesure le cœur de l’infarctus et la zone mal perfusée encore récupérable.","src":[{"id":"R-ESO-IVT","loc":"Recommandations 4,5 à 9 h et AVC du réveil","lu_le":"2026-10-17"},{"id":"R-ESO-MT","loc":"PICO 2, critères DEFUSE-3 et DAWN","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"avc-ischemique","label":"Accident vasculaire cérébral ischémique","pec":{"mesures_generales":["Le patient rejoint sans délai un centre de l’AVC, et l’équipe note l’heure de début ou celle où il a été vu sans déficit pour la dernière fois.","Une pression artérielle supérieure à 185/110 mmHg doit être abaissée avant la thrombolyse ; si elle reste plus haute, la thrombolyse n’est pas faite.","Aucun antithrombotique n’est donné dans les 24 heures qui suivent la thrombolyse."],"moyens_specifiques":[{"limites":"Elle augmente le risque d’hémorragie cérébrale symptomatique, d’environ 3 % avec l’altéplase : une hémorragie doit donc être exclue avant. Elle n’est pas faite si la pression reste au-dessus de 185/110 mmHg, si l’INR dépasse 1,7 sous antivitamine K, ou après un anticoagulant oral direct pris dans les 48 heures sans dosage spécifique.","mecanisme":"Le caillot prive de sang une zone qui meurt en quelques heures si le flux ne revient pas.","pourquoi_ce_choix":"Elle se donne par simple injection, sans attendre un centre de thrombectomie, et améliore le pronostic dans les 4,5 heures. La ténectéplase, plus spécifique de la fibrine et de durée d’action plus longue, se donne en une seule injection ; la ligne directrice la propose avant une thrombectomie.","principe":"On rétablit le flux en dissolvant le caillot : un médicament thrombolytique est injecté dans une veine.","src":[{"id":"R-ESO-IVT","loc":"Recommandations < 4,5 h, > 80 ans, ténectéplase, pression artérielle, anticoagulants ; hémorragie symptomatique","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La thrombolyse intraveineuse par altéplase ou ténectéplase se fait dans les 4,5 heures, y compris après 80 ans. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Elle ne concerne que l’occlusion d’une grosse artère prouvée par l’imagerie et exige un centre spécialisé ; ses complications propres restent À vérifier dans une source européenne.","mecanisme":"Un caillot dans une grosse artère menace un vaste territoire cérébral.","pourquoi_ce_choix":"Elle vise une reperfusion complète de la grosse artère ; elle améliore le pronostic jusqu’à 6 heures, et entre 6 et 24 heures si l’imagerie montre encore du tissu récupérable selon les critères des essais. La ligne directrice admet les deux techniques de retrait.","principe":"On rétablit le flux en retirant le caillot par un cathéter, avec un stent retriever ou par aspiration au contact.","src":[{"id":"R-ESO-MT","loc":"PICO 1, 2 et 8 ; Organisation des soins (mothership, drip-and-ship)","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La thrombectomie mécanique se fait dans un centre de l’AVC qui la pratique, en plus de la thrombolyse quand celle-ci est indiquée.","type":"interventionnel"}],"objectif":"Le traitement vise à rétablir le plus vite possible la perfusion du cerveau encore viable pour améliorer le pronostic fonctionnel."},"src":[{"id":"R-ESO-IVT","loc":"Résumé et recommandations","lu_le":"2026-10-17"},{"id":"R-ESO-MT","loc":"Résumé","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 1 Présentation typique","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site1-central"]},"bell":{"bloquant":false,"confirmation":"Le diagnostic est retenu devant une paralysie faciale périphérique installée en 12 à 72 heures, sans autre cause trouvée à l’examen et aux examens ciblés.","exam":{"lignes":[{"mecanisme":"Une paralysie faciale périphérique a une autre cause que la paralysie de Bell dans 25 à 40 % des cas.","nom":"Examen neurologique complet et otoscopie","pourquoi_ce_choix":"Ce sont des gestes immédiats qui écartent les causes graves ou spécifiques avant de retenir un diagnostic d’exclusion.","precautions":"Une atteinte bilatérale, plusieurs nerfs crâniens atteints, un spasme facial ou une évolution chronique sont atypiques et font rechercher une autre cause.","principe":"L’examen neurologique cherche d’autres déficits, et l’otoscopie cherche une cause dans l’oreille.","rang":1,"recherche":"Ils recherchent un autre déficit neurologique et des vésicules du conduit auditif externe, une otite moyenne ou un cholestéatome.","src":[{"id":"R-DGN-BELL","loc":"Was gibt es Neues ; Die wichtigsten Empfehlungen ; § 2.2","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Chez l’enfant, la ponction lombaire est obligatoire ; chez l’adulte, la ligne directrice allemande la recommande, alors que le protocole des HUG la réserve aux présentations atypiques.","mecanisme":"Une neuroborréliose, un diabète ou une infection peuvent donner le même tableau.","nom":"Sérologie de Borrelia, glycémie et hémoglobine glyquée ; sérologies VIH et syphilis selon le protocole des HUG","pourquoi_ce_choix":"La ligne directrice exige au moins la sérologie de Borrelia, car la neuroborréliose se traite par antibiotique et non par corticoïde ; une sérologie du virus varicelle-zona s’ajoute en cas de suspicion de zona.","principe":"Le sang montre des anticorps contre Borrelia, une glycémie élevée ou les marqueurs d’une infection.","rang":2,"recherche":"Elles recherchent une neuroborréliose, un diabète et une cause infectieuse.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5 Laboruntersuchungen","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 4 Examens complémentaires","lu_le":"2026-10-17"},{"id":"R-DGN-NB","loc":"§ 5.2.4, recommandation 15","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une tumeur ou une lésion du rocher peut imiter une paralysie de Bell, et la perte axonale détermine la récupération.","nom":"IRM et électroneuromyographie (ENMG)","pourquoi_ce_choix":"L’IRM n’est indiquée qu’en cas de présentation atypique ; l’ENMG vers le 10e jour évalue le pronostic des formes sévères.","precautions":"Une baisse de l’amplitude motrice de plus de 80 à 90 % annonce un risque accru de récupération incomplète.","principe":"L’IRM montre un processus le long du trajet du nerf ; l’ENMG mesure la réponse des muscles à la stimulation du nerf.","rang":3,"recherche":"L’IRM recherche un processus de l’angle ponto-cérébelleux, du rocher, de la parotide ou du tronc cérébral ; l’ENMG mesure la perte axonale.","src":[{"id":"R-DGN-BELL","loc":"§ 2.3 ; § 2.4 Bildgebung","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"bell","label":"Paralysie faciale idiopathique (paralysie de Bell)","pec":{"mesures_generales":["La sévérité est cotée selon House-Brackmann, et le patient est revu ; une forme sévère (grades IV à VI) est revue en neurologie vers le 10e jour.","Une grossesse ne change pas la conduite, mais la corticothérapie débute de préférence à l’hôpital avec un avis obstétrical."],"moyens_specifiques":[{"limites":"Le bénéfice n’est démontré que si le traitement débute dans les 72 heures ; des troubles du sommeil ont été rapportés, et les contre-indications restent À vérifier dans l’information professionnelle suisse.","mecanisme":"La cause reste discutée : la ligne directrice cite une inflammation auto-immune, une réactivation du virus herpès simplex de type 1 et des facteurs ischémiques.","pourquoi_ce_choix":"C’est le seul traitement dont les essais montrent qu’il favorise la récupération complète et réduit les syncinésies, avec un nombre de sujets à traiter de 10 ; un antiviral seul n’apporte pas ce bénéfice.","principe":"Le corticoïde agit contre la composante inflammatoire de l’atteinte du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 1 Einführung ; Die wichtigsten Empfehlungen ; Tabelle 3 et 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une corticothérapie orale débute dans les 72 heures. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Il ne remplace jamais le corticoïde ; la décision se prend au cas par cas après information du patient.","mecanisme":"Une réactivation du virus herpès simplex de type 1 fait partie des causes discutées.","pourquoi_ce_choix":"Il ne s’ajoute que dans les formes sévères, où il peut apporter un bénéfice supplémentaire : grades V et VI selon la ligne directrice allemande, grades IV à VI ou suspicion de zona selon le protocole des HUG.","principe":"Un antiviral freine la multiplication du virus en plus de l’effet du corticoïde.","src":[{"id":"R-DGN-BELL","loc":"Was gibt es Neues ; § 3.1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un antiviral peut s’ajouter au corticoïde dans les formes sévères. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"},{"limites":"Le délai et le choix de la technique restent À vérifier dans une source suisse ou européenne.","mecanisme":"Quand le nerf ne récupère pas, la paralysie devient définitive.","pourquoi_ce_choix":"Ces gestes ne se discutent qu’après l’échec de la récupération spontanée, qui reste la règle dans la paralysie de Bell.","principe":"On aide la fermeture des paupières ou l’on apporte au visage une autre commande nerveuse ou un autre muscle.","src":[{"id":"R-DGN-BELL","loc":"§ 2.6 Prognose ; § 3.2 Nicht medikamentöse Therapie","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une charge palpébrale ou une réanimation microchirurgicale peut être proposée (anastomose du nerf hypoglosse sur le nerf facial, greffe transfaciale, transfert musculaire).","type":"chirurgie"}],"objectif":"Le traitement vise une récupération complète et la prévention des séquelles, synergie et lésion de la cornée."},"src":[{"id":"R-DGN-BELL","loc":"Die wichtigsten Empfehlungen ; § 1 ; § 2 ; § 3","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 1 à 6","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site2-genicule","vii-site3-tympanique","vii-site4-mastoidien"]},"choc-cardiogenique":{"bloquant":true,"confirmation":"Le choc cardiogénique se confirme par une hypoperfusion clinique et biologique liée à une dysfonction cardiaque, que l’échocardiographie documente.","exam":{"lignes":[{"mecanisme":"Une dysfonction cardiaque sévère abaisse le débit cardiaque, et les organes manquent de sang et d’oxygène.","nom":"Signes cliniques d’hypoperfusion, avec ou sans hypotension","pourquoi_ce_choix":"La ligne directrice définit le choc cardiogénique par une hypoperfusion clinique avec une dysfonction cardiaque ; l’hypotension manque parfois, car la vasoconstriction maintient la pression au prix de la perfusion.","principe":"On palpe la température et la moiteur des extrémités, on mesure la diurèse, on recherche une confusion et un vertige, et on note la pression pulsée.","rang":1,"recherche":"Il recherche des extrémités froides et moites, une oligurie, une confusion, une pression pulsée pincée et des marbrures.","src":[{"id":"R-ESC-IC","loc":"§ 11.2.4","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’hypoperfusion fait passer les cellules au métabolisme anaérobie, qui produit du lactate et une acidose ; le rein mal perfusé retient la créatinine.","nom":"Lactate, pH, créatinine et ECG","pourquoi_ce_choix":"La ligne directrice retient ces anomalies comme critères biologiques d’hypoperfusion ; l’ECG cherche un syndrome coronarien aigu, cause la plus fréquente, qui impose une reperfusion immédiate.","principe":"On mesure le lactate et le pH sur un gaz du sang, on dose la créatinine, et on enregistre un ECG.","rang":2,"recherche":"Il recherche une hyperlactatémie, une acidose métabolique, une élévation de la créatinine et un sus-décalage du segment ST.","src":[{"id":"R-ESC-IC","loc":"§ 11.2.4 ; Table 20","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une complication mécanique d’un infarctus, une tamponnade ou une valvulopathie aiguë provoquent un choc qui demande un geste spécifique.","nom":"Échocardiographie immédiate","pourquoi_ce_choix":"Elle oriente le traitement de la cause : angioplastie, péricardiocentèse ou chirurgie valvulaire.","principe":"Les ultrasons au lit montrent la contraction des ventricules, les valves, le septum et le péricarde.","rang":3,"recherche":"Elle recherche une dysfonction ventriculaire sévère, une rupture mécanique, une insuffisance valvulaire aiguë ou une tamponnade.","src":[{"id":"R-ESC-IC","loc":"Figure 10","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"choc-cardiogenique","label":"Choc cardiogénique","pec":{"mesures_generales":["Le patient part vers un centre qui dispose de cardiologie interventionnelle, de soins intensifs et d’assistance circulatoire.","Un syndrome coronarien aigu reçoit une intervention coronarienne percutanée en urgence ; une tamponnade reçoit une péricardiocentèse ; une rupture de pilier mitral reçoit une chirurgie.","L’oxygène ou une ventilation se donnent en cas d’hypoxémie, sous surveillance continue de la pression artérielle, de la diurèse et du lactate."],"moyens_specifiques":[{"dose_ref":null,"limites":"La ligne directrice ne les recommande pas en routine, en raison de leurs risques, et ils exigent une surveillance continue.","mecanisme":"Un débit cardiaque bas et une pression artérielle basse ne perfusent plus les organes.","pourquoi_ce_choix":"Ils rétablissent la perfusion le temps de traiter la cause, avec une recommandation de faible niveau.","principe":"Un inotrope augmente la contraction du myocarde, et un vasopresseur augmente le tonus des artères.","src":[{"id":"R-ESC-IC","loc":"§ 11.3.5 et 11.3.6 ; Figure 10","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un inotrope s’envisage si la pression systolique est inférieure à 90 mmHg avec une hypoperfusion ; la noradrénaline se préfère comme vasopresseur dans le choc cardiogénique. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle comporte des complications et exige un centre spécialisé ; ses indications précises restent À vérifier dans la ligne directrice.","mecanisme":"Un choc qui persiste malgré les médicaments laisse le cœur incapable d’assurer le débit nécessaire aux organes.","pourquoi_ce_choix":"La ligne directrice la recommande, avec un niveau intermédiaire, quand les inotropes et les vasopresseurs ne suffisent plus.","principe":"Une assistance circulatoire mécanique de courte durée remplace une partie du travail du cœur par une pompe.","src":[{"id":"R-ESC-IC","loc":"§ 11.3.10 ; Figure 10","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une assistance circulatoire mécanique de courte durée s’envisage dans le choc réfractaire, comme pont vers la récupération, la décision ou une transplantation. Le ballon de contre-pulsion placé dans l’aorte ne se recommande pas en routine après un infarctus.","type":"interventionnel"}],"objectif":"Le traitement vise à traiter la cause le plus tôt possible, à rétablir la perfusion des organes et à limiter leur défaillance."},"src":[{"id":"R-ESC-IC","loc":"§ 11.2.4 et 11.3 ; Figure 10","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-dyspnee-congestive","urg-choc"]},"cholesteatome":{"bloquant":false,"confirmation":"Le diagnostic repose sur l’otoscopie, l’examen ORL et l’imagerie.","exam":{"lignes":[{"mecanisme":"Le cholestéatome grossit dans l’oreille moyenne et érode l’os jusqu’au canal facial ; la paralysie s’installe lentement.","nom":"Otoscopie","pourquoi_ce_choix":"Elle est simple et immédiate, et un début lent de la paralysie doit la faire répéter avec soin.","principe":"L’otoscopie montre le cholestéatome dans l’oreille moyenne.","rang":1,"recherche":"Elle recherche le cholestéatome dans l’oreille moyenne.","src":[{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’extension du cholestéatome et l’atteinte du canal facial décident de la chirurgie.","nom":"Examen ORL et imagerie du rocher","pourquoi_ce_choix":"La ligne directrice demande un examen ORL et une IRM devant un processus du rocher ; le choix précis de l’imagerie reste À vérifier.","principe":"L’examen ORL et l’imagerie précisent l’extension et l’état du canal facial.","rang":2,"recherche":"Ils précisent l’extension du cholestéatome et l’atteinte du canal facial.","src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1 ; § 2.4 ; § 2.5","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"cholesteatome","label":"Cholestéatome","pec":{"mesures_generales":["Le patient est adressé à un ORL.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les limites et les risques de l’intervention restent À vérifier dans une source suisse ou européenne.","mecanisme":"Le cholestéatome comprime et érode le canal facial.","pourquoi_ce_choix":"Le choix et les modalités de l’intervention restent À vérifier dans une source suisse ou européenne.","principe":"On retire le cholestéatome pour libérer le nerf.","statut":"À vérifier","texte":"Le cholestéatome est retiré par une chirurgie de l’oreille moyenne.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à enlever le cholestéatome et à libérer le nerf facial."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site3-tympanique"]},"corps-etranger-inhale":{"bloquant":true,"confirmation":"Le diagnostic est clinique, sur un étouffement brutal pendant un repas ; l’endoscopie confirme un corps étranger resté dans les voies aériennes.","exam":{"lignes":[{"mecanisme":"Un corps étranger, le plus souvent un aliment, bloque le larynx ou la trachée et empêche l’air de passer.","nom":"Reconnaissance de l’étouffement et de sa gravité","pourquoi_ce_choix":"La ligne directrice sépare l’obstruction légère, chez la victime qui parle, tousse et respire, de l’obstruction sévère, chez la victime qui ne parle plus, dont la toux faiblit et qui lutte pour respirer ; seule l’obstruction sévère reçoit des tapes et des compressions.","principe":"On demande à la victime consciente « Vous étouffez ? », puis on observe si elle parle, tousse et respire.","rang":1,"recherche":"Il recherche une incapacité soudaine de parler pendant un repas, une toux inefficace, un stridor, un tirage ou une cyanose.","src":[{"id":"R-ERC-BLS","loc":"Foreign body airway obstruction, Recognition","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Le corps étranger peut rester visible dans la bouche après une tape ou une compression.","nom":"Inspection de la bouche","pourquoi_ce_choix":"La ligne directrice déconseille le balayage à l’aveugle du doigt, qui peut enfoncer l’objet ou blesser les tissus.","principe":"On regarde dans la bouche et on retire avec le doigt seulement un objet clairement visible.","rang":2,"recherche":"Il recherche un objet visible dans la bouche ou dans l’oropharynx.","src":[{"id":"R-ERC-BLS","loc":"Foreign body airway obstruction, finger sweep","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Un fragment peut rester dans une bronche et donner plus tard une pneumonie ou une atélectasie.","nom":"Avis médical après la désobstruction, puis endoscopie si besoin","pourquoi_ce_choix":"La ligne directrice demande un avis médical en cas de toux persistante, de difficulté à avaler ou de sensation d’un objet encore coincé dans la gorge.","precautions":"Le recours à l’endoscopie et sa technique restent À vérifier dans une autre source.","principe":"Un médecin examine la victime ; si un fragment est suspecté, un spécialiste explore le larynx, la trachée et les bronches par un endoscope.","rang":3,"recherche":"Elle recherche un corps étranger résiduel, une lésion des voies aériennes ou une atélectasie.","src":[{"id":"R-ERC-BLS","loc":"Foreign body airway obstruction, Evidence","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"corps-etranger-inhale","label":"Corps étranger inhalé","pec":{"mesures_generales":["La victime qui tousse efficacement est encouragée à continuer de tousser, car la toux crée une pression élevée qui peut expulser l’objet.","Le sauveteur alerte les secours, et il reste avec la victime jusqu’à la désobstruction ou à l’arrivée de l’équipe.","Un œdème du larynx avec urticaire après une exposition à un allergène oriente vers une anaphylaxie, qui se traite par adrénaline intramusculaire."],"moyens_specifiques":[{"dose_ref":null,"limites":"Les tapes et les compressions peuvent blesser et même aggraver l’obstruction, d’où leur réserve à l’obstruction sévère ; toute victime traitée par compressions abdominales ou thoraciques doit être examinée par un professionnel qualifié.","mecanisme":"Quand la toux devient inefficace, la pression créée par la victime ne suffit plus à chasser le corps étranger.","pourquoi_ce_choix":"La ligne directrice recommande cette séquence, car les combinaisons de techniques réussissent plus souvent qu’une seule technique.","principe":"Les tapes dans le dos, puis les compressions abdominales, créent une pression brusque dans les voies aériennes qui pousse l’objet vers la bouche.","src":[{"id":"R-ERC-BLS","loc":"Foreign body airway obstruction, Treatment","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le sauveteur penche la victime en avant et donne jusqu’à 5 tapes entre les omoplates avec le talon de la main ; si elles échouent, il donne jusqu’à 5 compressions abdominales, le poing entre l’ombilic et les côtes, tiré vers l’intérieur et vers le haut. Il alterne ensuite 5 tapes et 5 compressions.","type":"autre"},{"dose_ref":null,"limites":"Un professionnel formé peut retirer l’objet sous laryngoscopie avec une pince de Magill, technique qui sort de la ligne directrice de base.","mecanisme":"Une victime qui perd connaissance n’a plus de ventilation efficace, et l’arrêt cardiaque suit l’hypoxie.","pourquoi_ce_choix":"La ligne directrice relie directement l’obstruction sévère à la réanimation, sans attendre la désobstruction.","principe":"Les compressions thoraciques de la réanimation font circuler le sang vers le cerveau et le cœur pendant l’arrêt de la ventilation.","src":[{"id":"R-ERC-BLS","loc":"Foreign body airway obstruction ; Fig. 3","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Si la victime perd connaissance, le sauveteur commence la réanimation cardio-pulmonaire selon l’algorithme de base.","type":"autre"}],"objectif":"Le traitement vise à expulser le corps étranger le plus tôt possible, avant que la victime ne perde connaissance."},"src":[{"id":"R-ERC-BLS","loc":"Foreign body airway obstruction","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-etouffement"]},"dissection-aortique":{"bloquant":true,"confirmation":"La dissection se confirme quand l’imagerie montre un voile intimal séparant un vrai et un faux chenal ; elle est de type A si elle atteint l’aorte ascendante, de type B sinon.","exam":{"lignes":[{"mecanisme":"La déchirure de l’intima et le faux chenal qui en naît donnent des signes typiques : terrain à risque, douleur brutale et déchirante, déficit de pouls, souffle d’insuffisance aortique, déficit neurologique.","nom":"Algorithme ADD-RS : score clinique, échocardiographie ciblée et D-dimères","pourquoi_ce_choix":"La ligne directrice recommande cet algorithme multiparamétrique pour décider vite qui doit passer à l’angioscanner, sans retarder le patient à haut risque.","precautions":"L’examen compare les pouls et la pression systolique des deux bras, ausculte le cœur à la recherche d’un souffle diastolique et recherche un déficit neurologique.","principe":"Le score ADD-RS compte ces signes en trois groupes ; l’échocardiographie transthoracique ciblée cherche un voile intimal, un épanchement péricardique ou une insuffisance aortique, et des D-dimères normaux avec un score bas rendent la dissection peu probable.","rang":1,"recherche":"Il recherche le terrain, les caractères de la douleur et les signes d’examen du score, puis les signes échographiques de dissection.","src":[{"id":"R-ESC-AORTE","loc":"§ 9.3.1.3, Recommendation Table 44, Figure 30","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Si le scanner manque, l’IRM peut le remplacer ; chez le patient instable qui ne peut pas aller au scanner, l’échocardiographie transœsophagienne pose le diagnostic.","mecanisme":"Le sang entre dans la paroi de l’aorte par la déchirure de l’intima et crée un faux chenal qui peut se rompre ou boucher des branches.","nom":"Angioscanner de l’aorte synchronisé à l’ECG, du cou au bassin","pourquoi_ce_choix":"La ligne directrice en fait l’imagerie de première intention, car il est disponible, précis et décrit toute l’aorte, ce qui distingue le type A, opéré en urgence, du type B.","principe":"Le produit de contraste opacifie les deux chenaux et montre le voile intimal, la porte d’entrée, l’extension et les complications.","rang":2,"recherche":"Il recherche un voile intimal, la porte d’entrée, l’extension, une malperfusion, une dilatation ou une rupture.","src":[{"id":"R-ESC-AORTE","loc":"§ 9.3.1.3, Recommendation Table 44","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les complications de la dissection proximale (insuffisance aortique, tamponnade, extension aux artères coronaires) changent le geste chirurgical.","nom":"Échocardiographie transœsophagienne","pourquoi_ce_choix":"Elle se fait au bloc ou au lit pour guider l’intervention et détecter les complications, et elle remplace le scanner chez le patient trop instable pour être transporté.","principe":"La sonde placée dans l’œsophage, au contact de l’aorte, montre en détail la valve aortique, la racine de l’aorte et le péricarde.","rang":3,"recherche":"Elle recherche une insuffisance aortique, un épanchement péricardique et l’atteinte de la racine aortique.","src":[{"id":"R-ESC-AORTE","loc":"Recommendation Table 44","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"dissection-aortique","label":"Dissection aortique","pec":{"mesures_generales":["Le patient est surveillé en soins intensifs, avec une mesure invasive de la pression artérielle.","La douleur se traite par des opiacés intraveineux, ce qui aide aussi à baisser la pression et la fréquence cardiaque."],"moyens_specifiques":[{"dose_ref":null,"limites":"En cas d’ischémie de la moelle épinière ou de malperfusion, une pression moyenne plus haute est recommandée. Le traitement à donner en cas de contre-indication aux bêtabloquants reste À vérifier dans l’algorithme de la ligne directrice.","mecanisme":"Chaque éjection du ventricule gauche pousse le sang dans le faux chenal et étend la déchirure de la paroi aortique.","pourquoi_ce_choix":"La ligne directrice place le bêtabloquant en première ligne, parce qu’il agit à la fois sur la fréquence et sur la pression, et n’ajoute le vasodilatateur qu’ensuite.","principe":"On diminue la force et la fréquence des éjections et la pression contre la paroi : c’est le traitement anti-impulsif.","src":[{"id":"R-ESC-AORTE","loc":"§ 9.3.1.4.1, Recommendation Table 45, Figure 31","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un bêtabloquant intraveineux (labétalol ou esmolol) vise une pression systolique inférieure à 120 mmHg et une fréquence cardiaque d’au plus 60 par minute ; un vasodilatateur intraveineux s’ajoute si la cible de pression n’est pas atteinte. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"La mortalité opératoire reste de 17 à 25 % ; un transfert vers un centre aortique à fort volume s’envisage s’il ne retarde pas l’intervention.","mecanisme":"Dans le type A, la dissection atteint l’aorte ascendante et menace de se rompre dans le péricarde ou d’atteindre la valve aortique et les artères coronaires.","pourquoi_ce_choix":"Sans chirurgie, la mortalité atteint environ 50 % dans les 48 premières heures, soit 1 à 2 % par heure.","principe":"On remplace l’aorte ascendante pour fermer la porte d’entrée et supprimer le faux chenal proximal.","src":[{"id":"R-ESC-AORTE","loc":"§ 9.3.1.4.2, Recommendation Table 46","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La dissection de type A impose un avis chirurgical et une intervention immédiats.","type":"chirurgie"},{"dose_ref":null,"limites":"Il exige une anatomie adaptée et un centre expérimenté ; ses complications propres restent À vérifier dans la ligne directrice.","mecanisme":"Dans le type B compliqué, le faux chenal de l’aorte descendante écrase le vrai chenal, prive de sang les viscères ou les membres, ou menace de se rompre.","pourquoi_ce_choix":"La ligne directrice préfère le TEVAR à la chirurgie ouverte quand une intervention est nécessaire et que l’anatomie s’y prête.","principe":"On couvre la porte d’entrée par une endoprothèse posée par voie endovasculaire, ce qui renvoie le flux dans le vrai chenal.","src":[{"id":"R-ESC-AORTE","loc":"§ 9.3.1.4.3, recommandations sur la dissection de type B","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le TEVAR (endoprothèse aortique thoracique) est recommandé dans la dissection de type B compliquée ; le type B non compliqué reçoit le traitement médical, et un TEVAR peut s’envisager chez certains patients entre 14 et 90 jours.","type":"interventionnel"}],"objectif":"Le traitement vise à empêcher la rupture et l’extension de la dissection, et à rétablir la perfusion des organes menacés."},"src":[{"id":"R-ESC-AORTE","loc":"§ 9.3","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-douleur-thoracique"]},"embolie-pulmonaire":{"bloquant":true,"confirmation":"L’embolie se confirme quand l’angioscanner montre un défaut de remplissage segmentaire ou plus proximal chez un patient de probabilité intermédiaire ou élevée ; chez le patient instable, une dysfonction du ventricule droit à l’échocardiographie suffit pour traiter.","exam":{"lignes":[{"mecanisme":"Le caillot, venu le plus souvent d’une thrombose veineuse profonde, est en partie dégradé dès sa formation et libère des D-dimères dans le sang.","nom":"Probabilité clinique par un score validé, puis D-dimères si elle n’est pas élevée","pourquoi_ce_choix":"Cette étape évite des scanners et une irradiation inutiles ; après 50 ans, un seuil ajusté à l’âge peut servir. Elle ne sert pas si la probabilité est élevée, car un résultat normal n’exclut pas alors l’embolie.","principe":"Un score validé (Wells ou Genève) ou le jugement clinique estime la probabilité ; chez un patient de probabilité faible ou intermédiaire, des D-dimères normaux excluent l’embolie sans imagerie.","rang":1,"recherche":"Il recherche des D-dimères élevés chez un patient dont la probabilité clinique n’est pas élevée.","src":[{"id":"R-ESC-EP","loc":"§ 4.1 et 4.2 ; Recommendations for diagnosis (5.6)","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Pendant la grossesse, une échographie veineuse de compression se fait d’abord si des signes de thrombose veineuse sont présents ; une scintigraphie de perfusion ou un angioscanner à faible dose s’envisage ensuite. Une scintigraphie de perfusion normale exclut aussi l’embolie.","mecanisme":"Le caillot bloque une ou plusieurs artères pulmonaires et y laisse un vide dans la colonne de sang opacifiée.","nom":"Angioscanner thoracique des artères pulmonaires","pourquoi_ce_choix":"Un défaut segmentaire ou plus proximal confirme l’embolie chez un patient de probabilité intermédiaire ou élevée, et un angioscanner normal l’exclut chez un patient de probabilité faible ou intermédiaire.","principe":"Le produit de contraste injecté dans une veine opacifie les artères pulmonaires, où le caillot apparaît comme un défaut de remplissage.","rang":2,"recherche":"Il recherche un défaut de remplissage dans les artères pulmonaires.","src":[{"id":"R-ESC-EP","loc":"Recommendations for diagnosis (5.6), CTPA ; § 9.1 grossesse","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une embolie massive surcharge brutalement le ventricule droit, qui se dilate et défaille, ce qui provoque le choc.","nom":"Échocardiographie au lit si le patient est instable","pourquoi_ce_choix":"Chez le patient instable, la ligne directrice admet l’échocardiographie au lit ou l’angioscanner en urgence selon la disponibilité ; une dysfonction du ventricule droit justifie alors le traitement de reperfusion.","principe":"L’échocardiographie au lit montre la dilatation et la dysfonction du ventricule droit sans déplacer le patient.","rang":3,"recherche":"Elle recherche une dilatation et une dysfonction du ventricule droit.","src":[{"id":"R-ESC-EP","loc":"Recommendations for diagnosis (5.6), suspected PE with haemodynamic instability","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"embolie-pulmonaire","label":"Embolie pulmonaire","pec":{"mesures_generales":["L’anticoagulation commence sans attendre la confirmation chez un patient de probabilité clinique élevée ou intermédiaire.","Le risque se classe selon l’état hémodynamique, le score PESI ou sPESI, la fonction du ventricule droit et la troponine.","Un patient en choc peut recevoir de la noradrénaline ou de la dobutamine, et une équipe multidisciplinaire peut organiser la reperfusion."],"moyens_specifiques":[{"dose_ref":null,"limites":"Les anticoagulants oraux directs ne se donnent pas en cas d’insuffisance rénale sévère, de syndrome des antiphospholipides, pendant la grossesse ni pendant l’allaitement ; pendant la grossesse, une héparine de bas poids moléculaire à dose fixe selon le poids les remplace.","mecanisme":"La coagulation continue de produire de la fibrine sur le caillot, qui peut alors s’étendre ou récidiver.","pourquoi_ce_choix":"La ligne directrice préfère l’anticoagulant oral direct à l’antivitamine K quand le patient y est éligible ; elle réserve l’héparine non fractionnée au patient instable, chez qui une reperfusion peut suivre.","principe":"On bloque la formation de nouvelle fibrine par un anticoagulant ; la fibrinolyse naturelle de l’organisme dissout ensuite le caillot existant.","src":[{"id":"R-ESC-EP","loc":"§ 6 ; Recommendations 6.7 et 9.1 ; Key messages, liste « what to do and what not to do »","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le patient stable reçoit une héparine de bas poids moléculaire ou du fondaparinux plutôt que de l’héparine non fractionnée, puis un anticoagulant oral direct (apixaban, dabigatran, édoxaban ou rivaroxaban) de préférence à un antivitamine K. Le patient instable reçoit de l’héparine non fractionnée intraveineuse avec un bolus adapté au poids. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle augmente le risque hémorragique, et elle n’est pas recommandée en routine dans l’embolie à risque intermédiaire ou faible. Ses contre-indications précises restent À vérifier dans la ligne directrice.","mecanisme":"Dans l’embolie à haut risque, l’obstruction massive des artères pulmonaires fait défaillir le ventricule droit et provoque un choc.","pourquoi_ce_choix":"Elle lève l’obstruction plus vite que l’anticoagulation seule, qui empêche l’extension sans dissoudre le caillot, et elle se donne sans plateau technique.","principe":"On dissout rapidement le caillot par un thrombolytique intraveineux pour diminuer la pression contre laquelle le ventricule droit éjecte.","src":[{"id":"R-ESC-EP","loc":"Recommendations 6.6 ; Key messages","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La thrombolyse systémique est recommandée dans l’embolie pulmonaire à haut risque ; une thrombolyse de sauvetage se fait si l’état se dégrade sous anticoagulation. Le produit et sa posologie restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elles exigent une équipe et un plateau expérimentés sur place ; une assistance circulatoire extracorporelle (ECMO) peut s’y associer en cas de collapsus réfractaire.","mecanisme":"Quand la thrombolyse est contre-indiquée ou échoue, le caillot continue d’obstruer les artères pulmonaires du patient en choc.","pourquoi_ce_choix":"Ces techniques offrent une reperfusion au patient chez qui le risque hémorragique interdit la thrombolyse ou chez qui elle n’a pas suffi.","principe":"On retire le caillot mécaniquement, par une intervention chirurgicale ou par un cathéter introduit jusqu’aux artères pulmonaires.","src":[{"id":"R-ESC-EP","loc":"Recommendations 6.6","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’embolectomie chirurgicale est recommandée, et le traitement percutané par cathéter s’envisage, chez le patient à haut risque dont la thrombolyse est contre-indiquée ou a échoué.","type":"chirurgie"}],"objectif":"Le traitement vise à empêcher l’extension du caillot et la récidive, et, en cas de choc, à lever l’obstruction pour soulager le ventricule droit."},"src":[{"id":"R-ESC-EP","loc":"§ 4 à 6 et 9","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-douleur-thoracique","urg-choc"]},"epiglottite":{"bloquant":true,"confirmation":"L’épiglottite se confirme par la vue directe d’une épiglotte rouge et gonflée à la laryngoscopie souple.","exam":{"lignes":[{"mecanisme":"L’infection fait gonfler l’épiglotte et le larynx au-dessus des cordes vocales, ce qui peut fermer les voies aériennes ; l’oropharynx paraît souvent normal.","nom":"Laryngoscopie souple par le nez","pourquoi_ce_choix":"La radiographie du cou ne trouve l’épiglottite que dans environ 79 % des cas ; la vue directe vient donc en premier, là où les voies aériennes peuvent être sécurisées.","principe":"Un fibroscope souple passé par le nez montre directement l’épiglotte et le larynx.","rang":1,"recherche":"Il recherche une épiglotte rouge et gonflée et un rétrécissement du passage de l’air.","src":[{"id":"R-NJM-EPI","loc":"Diagnosis","lu_le":"2026-10-17"}],"statut":"À vérifier"},{"mecanisme":"L’œdème progresse parfois en quelques heures, jusqu’à l’obstruction complète.","nom":"Surveillance rapprochée de la respiration et du stridor","pourquoi_ce_choix":"Un stridor annonce une obstruction qui avance ; un stridor qui diminue peut signifier une obstruction plus serrée, et non une guérison.","principe":"On suit la fréquence respiratoire, la saturation, le stridor, le tirage et la capacité à avaler la salive.","rang":2,"recherche":"Il recherche un stridor, un tirage, une dyspnée en position couchée ou une salive que le patient ne peut plus avaler.","src":[{"id":"R-NJM-EPI","loc":"Clinical presentation ; Discussion","lu_le":"2026-10-17"}],"statut":"À vérifier"},{"mecanisme":"L’épiglottite est une infection bactérienne, surtout à Haemophilus influenzae de type b et à streptocoques.","nom":"Hémocultures avant les antibiotiques","pourquoi_ce_choix":"Elles se prélèvent avant les antibiotiques pour identifier le germe et adapter le traitement.","principe":"Les hémocultures recherchent le germe dans le sang.","rang":3,"recherche":"Il recherche le germe en cause.","src":[{"id":"R-NJM-EPI","loc":"Treatment","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"epiglottite","label":"Épiglottite aiguë de l’adulte","pec":{"mesures_generales":["Le patient reste surveillé là où une intubation et un abord chirurgical des voies aériennes sont possibles à tout moment.","Il ne boit ni ne mange quand une intubation est envisagée.","Une forme légère, sans gêne respiratoire, peut être seulement surveillée."],"moyens_specifiques":[{"dose_ref":null,"limites":"Le geste demande une équipe entraînée ; en cas d’échec, seule la coniotomie ou la trachéotomie rétablit la respiration.","mecanisme":"L’œdème de l’épiglotte peut fermer brusquement les voies aériennes.","pourquoi_ce_choix":"Le fibroscope passe sous contrôle de la vue malgré un larynx déformé ; l’abord chirurgical sauve le patient si l’intubation échoue.","principe":"On garde le passage de l’air par une sonde placée dans la trachée.","src":[{"id":"R-NJM-EPI","loc":"Treatment ; Airway management","lu_le":"2026-10-17"}],"statut":"À vérifier","texte":"Une intubation par le nez sous fibroscope se préfère, avec une coniotomie ou une trachéotomie prête à être faite immédiatement.","type":"interventionnel"},{"dose_ref":null,"limites":"Un antibiotique donné au cabinet peut retarder l’envoi à l’hôpital ; le choix de la molécule dépend des résistances locales.","mecanisme":"Les bactéries entretiennent l’inflammation de l’épiglotte.","pourquoi_ce_choix":"Il traite la cause, alors que les gestes sur les voies aériennes traitent la menace immédiate.","principe":"Un antibiotique intraveineux actif sur Haemophilus influenzae et les streptocoques traite l’infection.","src":[{"id":"R-NJM-EPI","loc":"Treatment ; Discussion","lu_le":"2026-10-17"}],"statut":"À vérifier","texte":"Un antibiotique intraveineux commence après les hémocultures ; la molécule reste À vérifier dans les recommandations suisses. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Son bénéfice n’est pas démontré, et elle peut retarder l’envoi à l’hôpital quand elle est donnée en ville.","mecanisme":"L’inflammation fait gonfler l’épiglotte.","pourquoi_ce_choix":"Elle ne se donne qu’en complément, jamais à la place de la sécurisation des voies aériennes.","principe":"Un corticoïde comme la dexaméthasone pourrait réduire l’œdème.","src":[{"id":"R-NJM-EPI","loc":"Treatment ; Discussion","lu_le":"2026-10-17"}],"statut":"À vérifier","texte":"La dexaméthasone a été donnée dans la série de cas, mais son bénéfice reste incertain. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à garder les voies aériennes ouvertes et à traiter l’infection."},"src":[{"id":"R-NJM-EPI","loc":"texte complet","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["urg-etouffement"]},"etat-de-mal-epileptique":{"bloquant":true,"confirmation":"On parle d’état de mal épileptique quand une crise dure plus de 5 minutes, ou quand au moins deux crises se suivent sur plus de 5 minutes sans retour à l’état neurologique antérieur.","exam":{"lignes":[{"mecanisme":"Une hypoglycémie, un trouble des électrolytes, une intoxication, un sevrage ou un taux trop bas d’antiépileptique peuvent provoquer ou entretenir les crises.","nom":"Glycémie capillaire et bilan sanguin d’urgence","pourquoi_ce_choix":"Ces examens sont rapides et désignent une cause curable, comme l’hypoglycémie ; la ligne directrice les inclut dans le bilan initial.","principe":"La glycémie capillaire et le bilan sanguin (formule sanguine, électrolytes avec magnésium, fonctions du foie et des reins, créatine kinase, glucose, hormones thyroïdiennes, toxiques, taux d’antiépileptiques) cherchent une cause qui se corrige.","rang":1,"recherche":"Ils recherchent une hypoglycémie, un trouble métabolique, une intoxication ou un taux d’antiépileptique trop bas.","src":[{"id":"R-DGN-SE","loc":"Diagnostik, Laboruntersuchungen","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une lésion cérébrale aiguë, comme un AVC, une hémorragie, une tumeur ou une infection, peut être la cause de l’état de mal.","nom":"Scanner cérébral, ou IRM si elle est possible","pourquoi_ce_choix":"La ligne directrice demande d’emblée un scanner, ou si possible une IRM, pour trouver une cause qui demande son propre traitement.","principe":"L’imagerie cérébrale montre ces lésions structurelles.","rang":2,"recherche":"Elle recherche une lésion cérébrale à l’origine des crises.","src":[{"id":"R-DGN-SE","loc":"Zusammenfassung ; Diagnostik","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Dans l’état de mal non convulsif, les décharges électriques du cerveau persistent sans mouvements visibles.","nom":"Électroencéphalogramme","pourquoi_ce_choix":"Il est essentiel pour diagnostiquer et suivre l’état de mal non convulsif, et pour reconnaître des crises psychogènes non épileptiques.","principe":"L’électroencéphalogramme enregistre l’activité électrique du cerveau et montre ces décharges.","rang":3,"recherche":"Il recherche des décharges épileptiques persistantes.","src":[{"id":"R-DGN-SE","loc":"Zusammenfassung ; EEG","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"etat-de-mal-epileptique","label":"État de mal épileptique","pec":{"mesures_generales":["L’équipe protège le patient, libère les voies aériennes et donne de l’oxygène si la saturation est inférieure à 95 % ; elle reste prête à intuber.","Une voie veineuse stable se pose hors du pli du coude, et le pouls, la pression artérielle et l’ECG se surveillent.","Une hypoglycémie se corrige par du glucose intraveineux ; si un alcoolisme est suspecté, la thiamine se donne avant le glucose.","Une fièvre fait rechercher une infection, avec une ponction lombaire si nécessaire, et peut justifier une antibiothérapie précoce."],"moyens_specifiques":[{"dose_ref":null,"limites":"Elle peut déprimer la respiration, ce qui impose d’être prêt à intuber ; la ligne directrice exige une dose suffisante dès la première injection.","mecanisme":"Les décharges épileptiques se prolongent quand les mécanismes d’inhibition des neurones ne suffisent plus à les arrêter.","pourquoi_ce_choix":"Le lorazépam intraveineux et le midazolam intramusculaire ont le meilleur niveau de preuve ; le midazolam intramusculaire est au moins aussi efficace, parce qu’il se donne plus vite et sans voie veineuse.","principe":"On renforce l’inhibition neuronale par une benzodiazépine, qui agit en quelques minutes par voie intramusculaire, intraveineuse ou nasale.","src":[{"id":"R-DGN-SE","loc":"Therapie, Stufe 1","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le stade 1 repose sur une benzodiazépine à dose suffisante : lorazépam intraveineux, midazolam intramusculaire ou nasal, ou diazépam, avec une seule répétition possible. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"La ligne directrice signale que le lévétiracétam n’est pas autorisé pour cette indication en Europe ; son statut en Suisse et les contre-indications du valproate restent À vérifier.","mecanisme":"Une partie des états de mal résiste aux benzodiazépines, et les crises continuent malgré la première ligne.","pourquoi_ce_choix":"Une étude comparative a montré une efficacité semblable du lévétiracétam, de la fosphénytoïne et du valproate, avec un arrêt du status chez environ 45 à 47 % des patients ; la fosphénytoïne n’est pas autorisée en Suisse.","principe":"On ajoute un antiépileptique intraveineux d’action plus longue, qui agit par un autre mécanisme.","src":[{"id":"R-DGN-SE","loc":"Therapie, Stufe 2 ; Empfehlungen 18 und 19","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le stade 2 (état de mal résistant aux benzodiazépines) repose en premier choix sur le lévétiracétam ou le valproate intraveineux ; la phénytoïne et le phénobarbital restent des alternatives. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Ils exigent l’intubation, la ventilation et une surveillance de l’EEG ; leurs complications propres restent À vérifier dans la ligne directrice.","mecanisme":"L’état de mal réfractaire persiste malgré deux lignes de traitement antiépileptique.","pourquoi_ce_choix":"Ces anesthésiques arrêtent les crises que les antiépileptiques n’ont pas arrêtées ; dans un état de mal focal non convulsif réfractaire, on peut parfois renoncer au coma thérapeutique.","principe":"On supprime l’activité épileptique par un anesthésique intraveineux sous ventilation mécanique, en coma thérapeutique guidé par l’EEG.","src":[{"id":"R-DGN-SE","loc":"Therapie, Stufen 3 und 4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’état de mal réfractaire et super-réfractaire se traite en soins intensifs par propofol ou midazolam, seuls ou associés, ou par thiopental à dose anesthésique.","type":"interventionnel"}],"objectif":"Le traitement vise à arrêter les crises le plus vite possible et à traiter leur cause."},"src":[{"id":"R-DGN-SE","loc":"Zusammenfassung ; Diagnostik ; Therapie","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-crise-prolongee"]},"exacerbation-bpco":{"bloquant":true,"confirmation":"L’exacerbation se diagnostique sur une aggravation aiguë de la dyspnée, de la toux ou de l’expectoration chez un patient atteint de bronchopneumopathie chronique obstructive ; les gaz du sang classent l’insuffisance respiratoire.","exam":{"lignes":[{"mecanisme":"Une infection ou un autre déclencheur aggrave l’obstruction bronchique et la distension des poumons, et les muscles respiratoires se fatiguent.","nom":"Signes de gravité, saturation et facteurs de risque d’exacerbation sévère","pourquoi_ce_choix":"Le guide suisse retient comme facteurs de risque d’exacerbation sévère un volume expiratoire maximal par seconde inférieur à 50 %, une saturation actuelle inférieure à 90 %, des hospitalisations antérieures et des comorbidités ; une saturation inférieure à 90 % impose l’hospitalisation.","principe":"On mesure la saturation et la fréquence respiratoire, on recherche le tirage, et on note le volume expiratoire maximal par seconde habituel, les hospitalisations antérieures et les comorbidités.","rang":1,"recherche":"Il recherche une hypoxémie, une détresse respiratoire, une confusion et une expectoration devenue purulente.","src":[{"id":"R-LPS-BPCO","loc":"Traitement de l’exacerbation aiguë, page 18","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’épuisement des muscles respiratoires réduit la ventilation, et le gaz carbonique s’accumule.","nom":"Gaz du sang artériel","pourquoi_ce_choix":"La ligne directrice européenne recommande la ventilation non invasive dans l’insuffisance respiratoire hypercapnique aiguë ; seul le gaz du sang pose cette indication.","principe":"Le prélèvement artériel mesure le pH et la pression partielle de gaz carbonique.","rang":2,"recherche":"Il recherche une hypercapnie avec une acidose respiratoire.","src":[{"id":"R-ERS-BPCO","loc":"Recommendation 4 et Question 4","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une embolie pulmonaire, une insuffisance cardiaque ou un syndrome coronarien aigu peuvent imiter ou déclencher une exacerbation.","nom":"Diagnostics différentiels : embolie pulmonaire et maladie coronarienne","pourquoi_ce_choix":"Le guide suisse rappelle de penser à l’embolie pulmonaire et à la maladie coronarienne, fréquentes chez ces patients.","principe":"On enregistre un ECG et on pèse les arguments pour une embolie pulmonaire ou une atteinte cardiaque.","rang":3,"recherche":"Il recherche des signes d’ischémie, une arythmie, des signes de thrombose veineuse ou une congestion.","src":[{"id":"R-LPS-BPCO","loc":"Traitement de l’exacerbation aiguë, page 18 ; BPCO et maladies cardiovasculaires, page 19","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"exacerbation-bpco","label":"Exacerbation de bronchopneumopathie chronique obstructive","pec":{"mesures_generales":["L’oxygène se règle pour viser une saturation de 88 à 92 % chez le patient qui risque une hypercapnie.","Le patient revoit un médecin dans les 48 heures après une exacerbation légère à modérée, et dans les 24 à 48 heures après une exacerbation sévère.","Après une hospitalisation, la réadaptation respiratoire commence dans les 3 semaines qui suivent la sortie ; la ligne directrice ne la recommande pas pendant le séjour.","Une hospitalisation à domicile peut remplacer l’hospitalisation classique chez un patient choisi."],"moyens_specifiques":[{"dose_ref":null,"limites":"Ils provoquent une tachycardie et un tremblement, et ils ne traitent ni l’inflammation ni l’infection.","mecanisme":"L’obstruction bronchique s’aggrave pendant l’exacerbation et augmente le travail respiratoire.","pourquoi_ce_choix":"Le guide suisse les place en premier, quel que soit le degré de gravité.","principe":"Un bêta-2 mimétique et un anticholinergique inhalés relâchent le muscle bronchique par deux voies différentes.","src":[{"id":"R-LPS-BPCO","loc":"Traitement de l’exacerbation aiguë, page 18","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le patient augmente les bêta-2 mimétiques et les anticholinergiques inhalés. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Il expose à l’hyperglycémie, et la dose citée par le guide suisse n’a pas été vérifiée dans l’information professionnelle suisse.","mecanisme":"L’inflammation des bronches s’aggrave pendant l’exacerbation et prolonge l’obstruction.","pourquoi_ce_choix":"Les deux sources le recommandent pour une durée courte ; une décroissance progressive est inutile sans corticoïde systémique au cours des 4 dernières semaines.","principe":"Un corticoïde systémique de courte durée réduit cette inflammation.","src":[{"id":"R-ERS-BPCO","loc":"Recommendations 1 et 3","lu_le":"2026-10-17"},{"id":"R-LPS-BPCO","loc":"Traitement de l’exacerbation aiguë, page 18","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un corticoïde oral se donne pendant une durée courte, de 14 jours au plus selon la ligne directrice européenne et de 3 à 7 jours selon le guide suisse ; à l’hôpital, la voie orale se préfère à la voie intraveineuse si la voie digestive fonctionne. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Le choix de la molécule reste À vérifier selon les résistances locales et les recommandations suisses d’infectiologie.","mecanisme":"Une infection bactérienne déclenche une partie des exacerbations et entretient l’inflammation bronchique.","pourquoi_ce_choix":"La ligne directrice européenne le suggère chez le patient ambulatoire, avec un niveau de preuve modéré.","principe":"Un antibiotique réduit la charge bactérienne des voies aériennes.","src":[{"id":"R-ERS-BPCO","loc":"Recommendation 2","lu_le":"2026-10-17"},{"id":"R-LPS-BPCO","loc":"Traitement de l’exacerbation aiguë, page 18","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un antibiotique se donne au patient ambulatoire selon la ligne directrice européenne, et il s’ajoute dans l’exacerbation sévère selon le guide suisse ; le choix suit les résistances locales. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle exige une équipe formée et une surveillance rapprochée ; un échec impose l’intubation.","mecanisme":"L’épuisement des muscles respiratoires fait monter le gaz carbonique et baisser le pH.","pourquoi_ce_choix":"Elle réduit le besoin d’intubation, la mortalité, les complications et la durée du séjour ; la ligne directrice en fait une recommandation forte.","principe":"La ventilation non invasive aide chaque inspiration par un masque, ce qui soulage les muscles et élimine le gaz carbonique.","src":[{"id":"R-ERS-BPCO","loc":"Recommendation 4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La ventilation non invasive se recommande chez le patient hospitalisé en insuffisance respiratoire hypercapnique aiguë ou aiguë sur chronique.","type":"autre"}],"objectif":"Le traitement vise à lever l’obstruction bronchique, à corriger l’hypoxémie sans aggraver l’hypercapnie et à prévenir l’intubation."},"src":[{"id":"R-ERS-BPCO","loc":"Recommendations 1 à 6","lu_le":"2026-10-17"},{"id":"R-LPS-BPCO","loc":"Traitement de l’exacerbation aiguë, page 18","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-dyspnee-sifflante"]},"fracture-rocher":{"bloquant":false,"confirmation":"Le diagnostic repose sur le contexte traumatique et l’imagerie du rocher.","exam":{"lignes":[{"mecanisme":"Un traumatisme crânien peut fracturer le rocher et léser le nerf dans son canal osseux.","nom":"Scanner haute résolution du rocher","pourquoi_ce_choix":"Le choix du scanner plutôt que de l’IRM pour l’os n’est pas encore sourcé par une ligne directrice lue. Ce point reste À vérifier dans une ligne directrice suisse ou européenne.","principe":"Le scanner haute résolution montre l’os en détail, donc le trait de fracture et le canal facial.","rang":1,"recherche":"Il recherche le trait de fracture et son rapport avec le canal facial.","statut":"À vérifier"},{"mecanisme":"La récupération dépend de la continuité du nerf et de la part des fibres qui ont dégénéré.","nom":"Électroneuromyographie (ENMG)","pourquoi_ce_choix":"Une activité volontaire conservée prouve la continuité du nerf ; c’est le seul examen qui chiffre l’atteinte.","precautions":"Une baisse de l’amplitude motrice de plus de 80 à 90 % annonce un risque accru de récupération incomplète ; l’examen n’est informatif qu’après quelques jours.","principe":"On stimule le nerf au foramen stylo-mastoïdien et l’on mesure la réponse des muscles ; une baisse de l’amplitude traduit une perte axonale.","rang":2,"recherche":"Elle mesure la perte axonale et la continuité du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.3 Elektrophysiologische Diagnostik","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"fracture-rocher","label":"Fracture du rocher","pec":{"mesures_generales":["Un avis ORL est demandé.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les limites et les risques de l’intervention restent À vérifier dans une source européenne.","mecanisme":"Un fragment osseux peut comprimer le nerf, ou le nerf peut être sectionné.","pourquoi_ce_choix":"Les critères qui la font préférer à l’abstention restent À vérifier dans une source européenne.","principe":"On décomprime ou l’on répare le nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1","lu_le":"2026-10-17"}],"statut":"À vérifier","texte":"Une intervention chirurgicale sur le canal facial peut être indiquée.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à préserver ou à rétablir la continuité du nerf facial."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1 ; § 2.3","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site2-genicule","vii-site4-mastoidien"]},"hemorragie-digestive-haute":{"bloquant":true,"confirmation":"La lésion responsable se confirme à l’endoscopie digestive haute, qui la classe selon Forrest et la traite dans le même temps si elle saigne ou porte un vaisseau visible.","exam":{"lignes":[{"mecanisme":"Le sang perdu dans l’œsophage, l’estomac ou le duodénum diminue le volume circulant ; l’organisme compense d’abord par une tachycardie, puis la pression artérielle baisse.","nom":"État hémodynamique, indice de choc et score de Blatchford","pourquoi_ce_choix":"La ligne directrice demande d’évaluer l’état hémodynamique dès l’arrivée et recommande ce score avant l’endoscopie : un score de 0 ou 1 désigne un risque très faible, compatible avec une prise en charge ambulatoire.","principe":"On mesure le pouls et la pression artérielle, on calcule l’indice de choc, puis le score de Blatchford réunit l’urée, l’hémoglobine, la pression systolique, le pouls, le méléna, la syncope et les comorbidités.","rang":1,"recherche":"Il recherche une instabilité hémodynamique et classe le risque de récidive, de décès ou de besoin d’une intervention à l’hôpital.","src":[{"id":"R-ESGE-NVUGIH","loc":"Table 1, pre-endoscopy management, recommendations 1 et 4","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"La perte de globules rouges fait baisser l’hémoglobine avec retard, et un anticoagulant ou un antiagrégant entretient le saignement.","nom":"Hémoglobine, groupe sanguin, coagulation et liste des antithrombotiques","pourquoi_ce_choix":"Ces données décident de la transfusion selon un seuil d’hémoglobine et de la conduite à tenir pour chaque antithrombotique, sans retarder l’endoscopie.","precautions":"Une hémoglobine normale à l’arrivée n’exclut pas une perte importante, car l’hémodilution n’a pas encore eu lieu.","principe":"On dose l’hémoglobine et la coagulation, on détermine le groupe sanguin, et on note chaque antiagrégant plaquettaire et chaque anticoagulant avec l’heure de la dernière prise.","rang":2,"recherche":"Il recherche une anémie, un trouble de la coagulation et la prise d’aspirine, d’un second antiagrégant, d’un antivitamine K ou d’un anticoagulant oral direct.","src":[{"id":"R-ESGE-NVUGIH","loc":"Table 1, pre-endoscopy management, recommendations 2, 3 et 5 à 12","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Une cause variqueuse se suspecte chez un patient cirrhotique ; elle se traite selon la conférence de consensus Baveno VII, décrite dans l’hypothèse de l’hémorragie par rupture de varices.","mecanisme":"Un ulcère peptique qui saigne, ou qui porte un vaisseau visible, garde un risque élevé de saignement persistant ou de récidive.","nom":"Endoscopie digestive haute précoce, dans les 24 heures, avec classification de Forrest","pourquoi_ce_choix":"La ligne directrice recommande une endoscopie dans les 24 heures qui suivent la réanimation, et non dans les 12 heures, car l’endoscopie plus urgente n’améliore pas le pronostic ; la classification de Forrest désigne les lésions à traiter par endoscopie.","principe":"L’endoscope montre la lésion responsable ; la classification de Forrest décrit l’aspect de l’ulcère, du saignement en jet au fond propre.","rang":3,"recherche":"Il recherche un saignement actif en jet ou en nappe, un vaisseau visible non hémorragique, un caillot adhérent, une tache pigmentée ou un fond propre.","src":[{"id":"R-ESGE-NVUGIH","loc":"Table 1, endoscopic management, recommendations 1 à 4 et 7 à 10","lu_le":"2026-10-17"},{"id":"R-BAVENO7","loc":"6.17 et 6.21","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"hemorragie-digestive-haute","label":"Hémorragie digestive haute","pec":{"mesures_generales":["Le patient instable reçoit un remplissage intraveineux par des cristalloïdes dès l’évaluation hémodynamique.","La transfusion de globules rouges suit une stratégie restrictive : seuil de 7 grammes par décilitre d’hémoglobine sans maladie cardiovasculaire, seuil de 8 grammes par décilitre avec une maladie cardiovasculaire.","L’aspirine prise en prévention secondaire continue ; sous double antiagrégation, l’aspirine continue et le second antiagrégant s’interrompt, puis il reprend dans les 5 jours.","La ligne directrice ne recommande ni l’acide tranexamique, ni la somatostatine, ni le lavage par sonde nasogastrique, ni l’intubation systématique ; l’intubation se réserve à l’hématémèse active, à l’agitation ou à l’encéphalopathie."],"moyens_specifiques":[{"dose_ref":null,"limites":"Il ne remplace jamais l’endoscopie, et il ne traite pas une hémorragie variqueuse.","mecanisme":"L’acidité gastrique dissout le caillot formé sur l’ulcère et favorise la reprise du saignement.","pourquoi_ce_choix":"La ligne directrice recommande ce traitement après l’hémostase endoscopique, car il réduit la récidive ; avant l’endoscopie, il diminue les lésions qui exigent un geste.","principe":"Un inhibiteur de la pompe à protons à forte dose bloque la sécrétion acide, ce qui stabilise le caillot sur la lésion.","src":[{"id":"R-ESGE-NVUGIH","loc":"Table 1, pre-endoscopy recommendation 13 ; post-endoscopy recommendation 1","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un inhibiteur de la pompe à protons intraveineux à forte dose peut se donner avant l’endoscopie, sans la retarder ; après une hémostase endoscopique, il continue pendant 72 heures. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle exige un médecin formé à l’hémostase endoscopique, disponible jour et nuit ; un saignement réfractaire passe à l’embolisation.","mecanisme":"Un ulcère qui saigne en jet ou en nappe, ou qui porte un vaisseau visible, continue de saigner ou récidive sans geste local.","pourquoi_ce_choix":"La ligne directrice recommande cette association, car l’injection d’adrénaline seule échoue plus souvent qu’une double méthode.","principe":"On arrête le saignement par l’endoscope : une injection d’adrénaline diluée réduit le flux, puis une méthode thermique ou un clip ferme le vaisseau.","src":[{"id":"R-ESGE-NVUGIH","loc":"Table 1, endoscopic management, recommendations 6 et 13 à 17 ; post-endoscopy recommendations 3 et 4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un saignement actif reçoit une injection d’adrénaline associée à une seconde méthode d’hémostase ; un vaisseau visible reçoit une méthode thermique, mécanique ou sclérosante. Une récidive reçoit une nouvelle endoscopie, si besoin avec un clip monté sur capuchon.","type":"interventionnel"},{"dose_ref":null,"limites":"Elle exige un radiologue interventionnel disponible et un patient assez stable pour le transfert en salle d’angiographie.","mecanisme":"Quand l’endoscopie échoue deux fois, le vaisseau de l’ulcère reste ouvert et le patient continue de perdre du sang.","pourquoi_ce_choix":"La ligne directrice la place avant la chirurgie, qui reste indiquée si l’embolisation manque sur place ou échoue.","principe":"On bouche l’artère responsable par un cathéter introduit dans les artères digestives, ou on la ligature par une intervention chirurgicale.","src":[{"id":"R-ESGE-NVUGIH","loc":"Table 1, endoscopic management, recommendation 18 ; post-endoscopy recommendation 5","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’embolisation artérielle par voie endovasculaire s’envisage après l’échec de la seconde endoscopie ; la chirurgie s’indique si l’embolisation manque sur place ou échoue.","type":"interventionnel"}],"objectif":"Le traitement vise à restaurer le volume circulant, à arrêter le saignement par l’endoscopie et à prévenir la récidive."},"src":[{"id":"R-ESGE-NVUGIH","loc":"Table 1 ; pre-endoscopy, endoscopic and post-endoscopy management","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-hemorragie-digestive"]},"hemorragie-variceale":{"bloquant":true,"confirmation":"L’hémorragie variqueuse se confirme à l’endoscopie, qui montre une varice qui saigne, ou une varice sans autre lésion chez un patient cirrhotique qui saigne.","exam":{"lignes":[{"mecanisme":"Plus la cirrhose est grave, plus le risque d’échec de l’hémostase et de décès augmente.","nom":"Gravité de la cirrhose : score de Child et Pugh et score MELD","pourquoi_ce_choix":"La classe C du score de Child et Pugh, un MELD élevé et l’échec de l’hémostase prédisent la mortalité à six semaines ; ils désignent aussi les patients qui gagnent à recevoir un TIPS précoce.","principe":"Le score de Child et Pugh et le score MELD résument la fonction du foie à partir de la prise de sang et de l’examen clinique.","rang":1,"recherche":"Il recherche une cirrhose de classe B ou C et un MELD élevé.","src":[{"id":"R-BAVENO7","loc":"6.15 et 6.16 ; 6.27","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’hypertension portale dilate les veines de l’œsophage et de l’estomac, qui finissent par se rompre.","nom":"Endoscopie digestive haute dans les 12 heures","pourquoi_ce_choix":"La conférence de consensus demande l’endoscopie dans les 12 heures après la réanimation initiale, et dès que possible chez le patient instable ; une perfusion d’érythromycine avant l’examen vide l’estomac du sang, sauf en cas d’allongement du QT.","principe":"L’endoscope montre la varice qui saigne et permet de la traiter dans le même temps.","rang":2,"recherche":"Il recherche des varices de l’œsophage ou de l’estomac qui saignent ou portent un caillot.","src":[{"id":"R-BAVENO7","loc":"6.17 et 6.19","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une thrombose de la veine porte ou un carcinome du foie peuvent aggraver l’hypertension portale et le saignement.","nom":"Scanner ou imagerie par résonance magnétique avec injection","pourquoi_ce_choix":"Elle prépare un TIPS et recherche une cause qui change la prise en charge.","principe":"L’imagerie en coupes avec produit de contraste montre la veine porte, le foie et les veines collatérales.","rang":3,"recherche":"Il recherche une thrombose de la veine porte, un carcinome hépatocellulaire et des voies collatérales.","src":[{"id":"R-BAVENO7","loc":"6.26","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"hemorragie-variceale","label":"Hémorragie digestive par rupture de varices","pec":{"mesures_generales":["Le remplissage vasculaire restaure la perfusion des organes sans viser une pression normale.","La transfusion de globules rouges suit une stratégie restrictive, avec un seuil entre 7 et 8 grammes par décilitre d’hémoglobine.","L’intubation avant l’endoscopie se réserve au patient dont la conscience est altérée ou qui vomit activement du sang ; l’extubation suit le plus tôt possible.","Le patient est surveillé en soins intensifs ou intermédiaires ; l’alimentation orale reprend dès que possible.","La conférence de consensus ne recommande ni le plasma frais congelé, ni le facteur VII activé, ni l’acide tranexamique ; les anticoagulants s’interrompent temporairement."],"moyens_specifiques":[{"dose_ref":null,"limites":"La terlipressine peut provoquer une hyponatrémie, surtout quand la fonction du foie est conservée, ce qui impose une surveillance du sodium.","mecanisme":"L’hypertension portale pousse le sang dans les varices, qui se rompent sous la pression.","pourquoi_ce_choix":"La conférence de consensus les recommande avec le plus haut niveau de preuve, car ils aident à contrôler le saignement.","principe":"Un médicament vasoactif resserre les artères de l’intestin, ce qui réduit le débit et la pression dans la veine porte.","src":[{"id":"R-BAVENO7","loc":"6.5 et 6.6","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La terlipressine, la somatostatine ou l’octréotide commencent dès que l’hémorragie variqueuse est suspectée, avant l’endoscopie, et continuent 2 à 5 jours. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Le bénéfice reste incertain dans une cirrhose de classe A, où le risque d’infection est très faible.","mecanisme":"Le patient cirrhotique qui saigne fait souvent une infection bactérienne, qui aggrave le pronostic.","pourquoi_ce_choix":"Elle fait partie intégrante du traitement selon la conférence de consensus ; le choix suit les résistances locales.","principe":"Une antibioprophylaxie dès l’admission prévient ces infections.","src":[{"id":"R-BAVENO7","loc":"6.7 à 6.9","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une antibioprophylaxie commence dès l’admission ; la ceftriaxone intraveineuse se choisit dans une cirrhose avancée, quand les bactéries résistantes aux quinolones sont fréquentes, ou après une prophylaxie par quinolone. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"La poudre hémostatique ne se donne pas en première intention ; elle sert seulement de pont en attendant un traitement définitif.","mecanisme":"La varice rompue continue de saigner tant que sa paroi reste ouverte.","pourquoi_ce_choix":"La conférence de consensus recommande ces gestes, plus efficaces que les autres méthodes endoscopiques sur chaque type de varice.","principe":"On ferme la varice par l’endoscope : une ligature élastique serre la varice de l’œsophage, une colle tissulaire obstrue la varice isolée de l’estomac.","src":[{"id":"R-BAVENO7","loc":"6.21, 6.22 et 6.24","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La ligature élastique traite les varices de l’œsophage ; la colle tissulaire traite les varices isolées de l’estomac et celles qui prolongent la grande courbure.","type":"interventionnel"},{"dose_ref":null,"limites":"Il devient inutile quand le score de Child et Pugh atteint 14 ou quand le MELD dépasse 30 avec un lactate supérieur à 12 millimoles par litre ; il expose à l’encéphalopathie hépatique, que le lactulose aide à prévenir.","mecanisme":"La pression portale reste élevée et fait récidiver le saignement chez le patient le plus grave.","pourquoi_ce_choix":"Le TIPS précoce améliore la survie chez ces patients à haut risque, selon la conférence de consensus.","principe":"Le TIPS relie la veine porte à une veine du foie par une prothèse, ce qui abaisse aussitôt la pression portale.","src":[{"id":"R-BAVENO7","loc":"6.27 à 6.33","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un TIPS précoce, idéalement dans les 24 heures et au plus tard dans les 72 heures, se pose chez le patient de classe C avec un score de Child et Pugh inférieur à 14, ou de classe B au-delà de 7 avec un saignement actif à l’endoscopie. En cas d’échec, un ballon de tamponnement ou une prothèse œsophagienne sert de pont vers un TIPS de sauvetage.","type":"interventionnel"}],"objectif":"Le traitement vise à restaurer la perfusion, à arrêter le saignement par les médicaments vasoactifs et l’endoscopie, et à prévenir la récidive, l’infection et l’encéphalopathie hépatique."},"src":[{"id":"R-BAVENO7","loc":"chapitre 6, Management of acute variceal bleeding","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-hemorragie-digestive"]},"hyperkaliemie":{"bloquant":true,"confirmation":"L’hyperkaliémie se définit par une kaliémie supérieure à 5,5 millimoles par litre ; elle devient menaçante quand elle est sévère ou qu’elle modifie l’ECG.","exam":{"lignes":[{"mecanisme":"L’excès de potassium autour des cellules modifie leur potentiel de repos et ralentit la conduction dans le cœur.","nom":"Électrocardiogramme","pourquoi_ce_choix":"C’est l’outil diagnostique le plus vite disponible, et un ECG toxique associé à une kaliémie sévère impose le calcium intraveineux.","precautions":"Un ECG normal n’exclut pas une hyperkaliémie sévère, dont le premier signe peut être une arythmie ou un arrêt cardiaque.","principe":"L’électrocardiogramme montre des ondes T amples et pointues, un sous-décalage du segment ST, un QRS élargi, une bradycardie ou une tachycardie ventriculaire.","rang":1,"recherche":"Il recherche les signes électriques de toxicité du potassium.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia, ECG features ; Fig. 4","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’insuffisance rénale, certains médicaments ou la destruction de cellules font monter le potassium du plasma.","nom":"Kaliémie au lit (gaz du sang), confirmée au laboratoire","pourquoi_ce_choix":"La gravité se classe sur la kaliémie, modérée entre 6,0 et 6,4 millimoles par litre et sévère à partir de 6,5, et ce classement guide le traitement.","precautions":"Une hémolyse du prélèvement ou de mauvaises conditions de conservation peuvent donner une fausse hyperkaliémie.","principe":"Le gaz du sang au lit mesure le potassium en quelques minutes, et le laboratoire le confirme.","rang":2,"recherche":"Il recherche le niveau de la kaliémie.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia, Definition, Causes, Treatment","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"hyperkaliemie","label":"Hyperkaliémie","pec":{"mesures_generales":["Le patient est évalué selon l’approche ABCDE et placé sous monitorage cardiaque si l’hyperkaliémie est sévère.","La kaliémie et la glycémie se contrôlent de façon répétée pendant le traitement.","La cause, comme un médicament ou une insuffisance rénale, se recherche et se supprime pour prévenir la récidive."],"moyens_specifiques":[{"dose_ref":null,"limites":"Ils ne font pas baisser le potassium ; une extravasation provoque une nécrose des tissus, ce qui exige une voie veineuse sûre.","mecanisme":"L’excès de potassium rend le myocarde instable et l’expose aux arythmies et à l’arrêt cardiaque.","pourquoi_ce_choix":"Ils agissent en premier pour prévenir les arythmies et l’arrêt cardiaque, même si cette pratique repose sur un faible niveau de preuve.","principe":"Le calcium intraveineux protège les cellules cardiaques contre les arythmies, sans faire baisser la kaliémie.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia, Treatment","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Les sels de calcium intraveineux (chlorure ou gluconate) se donnent en cas d’hyperkaliémie sévère avec des signes à l’ECG. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle provoque une hypoglycémie chez jusqu’à 28 % des patients, surtout si la glycémie de départ est basse ; le salbutamol peut échouer sous bêtabloquant non sélectif et chez une partie des insuffisants rénaux terminaux.","mecanisme":"Le potassium en excès reste dans le plasma, alors que les cellules peuvent en stocker une grande quantité.","pourquoi_ce_choix":"L’insuline avec du glucose est le traitement le plus efficace et le plus fiable pour faire baisser vite la kaliémie, et son association au salbutamol agit mieux que chacun seul.","principe":"L’insuline, donnée avec du glucose, fait entrer le potassium dans les cellules, et le salbutamol renforce cet effet.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia, Treatment","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’insuline rapide avec du glucose intraveineux se donne en cas d’hyperkaliémie modérée ou sévère, suivie d’une perfusion de glucose si la glycémie de départ est basse ; le salbutamol peut s’y ajouter. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Le cyclosilicate de zirconium sodique agit en une heure environ, trop lentement pour remplacer les mesures d’urgence ; la dialyse exige un accès vasculaire et un centre équipé.","mecanisme":"Tant que le potassium n’est pas éliminé, la kaliémie remonte quand l’effet du transfert dans les cellules s’épuise.","pourquoi_ce_choix":"Ce sont les seuls moyens qui diminuent le stock de potassium, alors que le calcium et l’insuline agissent seulement sur ses effets ou sur sa répartition.","principe":"On retire le potassium de l’organisme par un chélateur intestinal ou par la dialyse.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia, Treatment ; Fig. 4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un chélateur oral du potassium (cyclosilicate de zirconium sodique ou patiromer) retire le potassium, et la dialyse s’envisage en cas d’hyperkaliémie réfractaire. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à protéger le cœur, à faire rentrer le potassium dans les cellules, puis à l’éliminer et à prévenir la récidive."},"src":[{"id":"R-ERC-SPEC","loc":"Hypo-/hyperkalaemia and other electrolyte disorders","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-hyperkaliemie"]},"hypoglycemie-severe":{"bloquant":true,"confirmation":"L’hypoglycémie se confirme par la triade de Whipple : des symptômes typiques, une glycémie basse mesurée au même moment, et la disparition des symptômes quand la glycémie remonte.","exam":{"lignes":[{"mecanisme":"Le cerveau dépend d’un apport continu de glucose ; quand la glycémie baisse, les neurones fonctionnent mal, puis la conscience s’altère.","nom":"Glycémie capillaire immédiate devant tout trouble de la conscience ou du comportement","pourquoi_ce_choix":"Les symptômes de l’hypoglycémie ne sont pas spécifiques ; la ligne directrice fonde le diagnostic sur une glycémie basse mesurée en même temps que les symptômes.","principe":"Une goutte de sang capillaire donne la glycémie en moins d’une minute au lit du patient.","rang":1,"recherche":"Il recherche une glycémie basse ; la ligne directrice ne fixe pas de seuil unique et cite celui de 3,9 millimoles par litre retenu aux États-Unis.","src":[{"id":"R-DDG-T1","loc":"§ 9.1.1 et 9.1.2","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"La baisse du glucose active d’abord le système nerveux autonome, puis, si elle continue, prive le cerveau de glucose.","nom":"Gravité clinique : capacité à avaler, conscience et convulsions","pourquoi_ce_choix":"La ligne directrice classe l’hypoglycémie comme sévère quand le patient a besoin d’une aide extérieure ; la conscience choisit la voie du sucre.","principe":"On note si le patient peut se traiter seul, s’il est conscient et s’il convulse, puis on recherche les sueurs, le tremblement, la faim et les palpitations.","rang":2,"recherche":"Il recherche une confusion, un trouble de la parole, un trouble visuel, une somnolence, une incoordination, une convulsion ou un coma.","src":[{"id":"R-DDG-T1","loc":"§ 9.1.1 et 9.1.2 ; Tabelle 19","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Chez le diabétique de type 1, une hypoglycémie traduit toujours un excès absolu ou relatif d’insuline.","nom":"Cause et traitement responsable","pourquoi_ce_choix":"La ligne directrice liste ces causes, dont l’insuffisance rénale, qui ralentit l’élimination de l’insuline ; la durée du risque sous sulfamide hypoglycémiant reste À vérifier.","principe":"On revoit la dose et l’heure de l’insuline, les repas, l’effort, l’alcool et la fonction rénale ; chez le diabétique de type 2, on revoit aussi un sulfamide hypoglycémiant.","rang":3,"recherche":"Il recherche une erreur de dose, un repas sauté, un effort, de l’alcool ou une insuffisance rénale.","src":[{"id":"R-DDG-T1","loc":"§ 9.1.2","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"hypoglycemie-severe","label":"Hypoglycémie sévère","pec":{"mesures_generales":["L’équipe vérifie d’abord les voies aériennes, la respiration, la circulation, la conscience et la température ; une perfusion d’insuline en cours s’arrête aussitôt.","La glycémie capillaire se contrôle 10 à 15 minutes après chaque traitement, et le traitement se répète si elle reste basse.","Une fois la glycémie remontée et le patient réveillé, il reçoit un glucide d’action lente ; la surveillance de la glycémie capillaire continue au moins 24 à 48 heures.","L’insuline prévue ne s’omet pas, mais son schéma se revoit."],"moyens_specifiques":[{"dose_ref":null,"limites":"Il ne convient pas au patient inconscient, qui reçoit du glucose par voie veineuse ou du glucagon.","mecanisme":"Le patient conscient qui avale peut absorber du sucre par la bouche, qui passe vite dans le sang.","pourquoi_ce_choix":"C’est le traitement recommandé du patient conscient, avec un consensus fort ; son effet se voit directement.","principe":"Un glucide d’action rapide remonte la glycémie en quelques minutes.","src":[{"id":"R-DDG-T1","loc":"Empfehlung 9-1 et 9-2 ; Tabelle 20","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le patient conscient reçoit un glucide rapide par la bouche, de préférence du glucose ; la glycémie se contrôle 15 minutes plus tard, le traitement se répète si elle reste basse, puis le patient prend un repas ou une collation. Les quantités restent À vérifier dans la ligne directrice et le protocole local.","type":"pharmaco"},{"dose_ref":null,"limites":"Le glucagon peut faire vomir, avec un risque de fausse route ; son efficacité réduite chez le patient dénutri ou alcoolique reste À vérifier.","mecanisme":"Le patient inconscient, en convulsions ou incapable d’avaler ne peut pas recevoir de sucre par la bouche.","pourquoi_ce_choix":"Le glucose intraveineux se préfère quand une voie veineuse existe ; le glucagon permet à un proche formé de traiter sans voie veineuse.","principe":"Le glucose intraveineux apporte directement le sucre au sang ; le glucagon libère le glycogène stocké dans le foie.","src":[{"id":"R-DDG-T1","loc":"Empfehlung 9-3 et 9-4 ; Tabelle 20","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le patient inconscient reçoit un bolus de glucose concentré par voie intraveineuse ; sans voie veineuse, il reçoit du glucagon par voie nasale, sous-cutanée ou intramusculaire. Le traitement se répète en l’absence de réponse après 5 minutes, puis le patient prend un repas ou une collation. La concentration du glucose et les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à remonter la glycémie au-dessus de 4,0 millimoles par litre en quelques minutes, puis à prévenir la récidive."},"src":[{"id":"R-DDG-T1","loc":"§ 9.1 Hypoglykämie","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-confusion-metabolique","urg-deficit-neuro-brutal"]},"hyponatremie":{"bloquant":true,"confirmation":"L’hyponatrémie se confirme par un sodium sérique inférieur à 135 millimoles par litre ; l’osmolalité plasmatique confirme son caractère hypotonique.","exam":{"lignes":[{"mecanisme":"La baisse du sodium rend le plasma hypotonique ; l’eau entre dans les cellules du cerveau, qui gonflent dans la boîte crânienne.","nom":"Natrémie, gravité biochimique, durée et symptômes","pourquoi_ce_choix":"La ligne directrice classe l’hyponatrémie en légère de 130 à 135, modérée de 125 à 129 et profonde au-dessous de 125 millimoles par litre ; les symptômes sévères sont les vomissements, la détresse cardio-respiratoire, la somnolence profonde, les convulsions et le coma.","principe":"On mesure le sodium sérique, on estime si la baisse date de moins de 48 heures, et on classe les symptômes.","rang":1,"recherche":"Il recherche des nausées, une confusion, une céphalée, des vomissements, une somnolence, des convulsions et un score de Glasgow de 8 ou moins.","src":[{"id":"R-ESE-HNA","loc":"§ 2.1.1 à 2.1.3 ; Table 1","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une glycémie élevée ou d’autres osmoles abaissent le sodium sans rendre le plasma hypotonique.","nom":"Osmolalité plasmatique et glycémie","pourquoi_ce_choix":"La ligne directrice recommande d’exclure d’abord l’hyponatrémie hyperglycémique ; une osmolalité inférieure à 275 milliosmoles par kilogramme signe toujours une hyponatrémie hypotonique.","principe":"On mesure l’osmolalité plasmatique et la glycémie, et on corrige le sodium pour la glycémie si elle est élevée.","rang":2,"recherche":"Il recherche une hyperglycémie, un plasma hypertonique ou une fausse hyponatrémie.","src":[{"id":"R-ESE-HNA","loc":"§ 2.2 ; Table 3","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Le rein dilue normalement l’urine en cas d’excès d’eau ; une sécrétion d’hormone antidiurétique ou une perte rénale de sel l’en empêche.","nom":"Osmolalité et sodium urinaires sur un échantillon, puis volume extracellulaire","pourquoi_ce_choix":"La ligne directrice propose cet ordre : une osmolalité urinaire inférieure ou égale à 100 milliosmoles par kilogramme oriente vers un excès d’eau ; au-dessus, un sodium urinaire inférieur ou égal à 30 millimoles par litre oriente vers un volume artériel efficace bas.","principe":"On mesure l’osmolalité urinaire, puis le sodium urinaire sur un échantillon prélevé en même temps que le sang, et on évalue le volume extracellulaire.","rang":3,"recherche":"Il recherche un excès d’apport d’eau, une hypovolémie, une surcharge ou un syndrome de sécrétion inappropriée d’hormone antidiurétique.","src":[{"id":"R-ESE-HNA","loc":"§ 2.3 ; Fig. 1","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"hyponatremie","label":"Hyponatrémie","pec":{"mesures_generales":["Le patient atteint de symptômes sévères reste dans un lieu où la surveillance biologique et clinique est étroite.","La hausse du sodium ne dépasse pas 10 millimoles par litre pendant les premières 24 heures, puis 8 millimoles par litre par 24 heures, jusqu’à 130 millimoles par litre.","Le sodium se contrôle à 6 et 12 heures, puis chaque jour, et toutes les 4 heures tant que le soluté hypertonique coule.","Dans l’hyponatrémie modérée ou profonde sans symptômes graves, la restriction hydrique est le traitement de première ligne d’un syndrome de sécrétion inappropriée."],"moyens_specifiques":[{"dose_ref":null,"limites":"Une correction trop rapide expose au syndrome de démyélinisation osmotique ; un dépassement des limites impose une intervention qui fait redescendre le sodium.","mecanisme":"L’œdème cérébral de l’hyponatrémie symptomatique sévère menace la vie en quelques heures.","pourquoi_ce_choix":"La ligne directrice vise une hausse de 5 millimoles par litre dans la première heure et recommande ce traitement que l’hyponatrémie soit aiguë ou chronique.","principe":"Une solution saline hypertonique augmente vite le sodium plasmatique, ce qui fait sortir l’eau des cellules cérébrales.","src":[{"id":"R-ESE-HNA","loc":"§ 3.1.1 à 3.1.3 et 3.5","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un soluté salé hypertonique à 3 % se perfuse en 20 minutes, se répète selon le sodium contrôlé, jusqu’à une hausse de 5 millimoles par litre ou jusqu’à l’amélioration ; il s’arrête quand les symptômes cèdent, quand le sodium a monté de 10 millimoles par litre ou quand il atteint 130. Le volume et le nombre de bolus restent À vérifier dans la ligne directrice.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle agit lentement, et elle ne convient pas à l’hyponatrémie hypovolémique, qui demande un apport de sel et d’eau.","mecanisme":"Dans le syndrome de sécrétion inappropriée d’hormone antidiurétique, le rein retient l’eau libre et dilue le sodium.","pourquoi_ce_choix":"Elle traite le mécanisme sans médicament et sans risque de correction trop rapide.","principe":"La restriction de l’apport d’eau réduit l’excès d’eau libre.","src":[{"id":"R-ESE-HNA","loc":"§ 3.4.3 et 3.4.4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La restriction hydrique se propose en première ligne dans l’hyponatrémie modérée ou profonde ; l’urée orale ou un diurétique de l’anse à faible dose avec du chlorure de sodium oral sont des secondes lignes équivalentes. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"autre"}],"objectif":"Le traitement vise à faire disparaître les symptômes graves par une correction rapide mais limitée, puis à traiter la cause sans dépasser les limites de correction."},"src":[{"id":"R-ESE-HNA","loc":"§ 2 et 3","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-confusion-metabolique"]},"insuffisance-cardiaque-aigue":{"bloquant":true,"confirmation":"L’insuffisance cardiaque aiguë se confirme par des signes de congestion avec des peptides natriurétiques élevés et une anomalie cardiaque à l’échocardiographie.","exam":{"lignes":[{"mecanisme":"Le cœur défaillant fait monter la pression dans les veines pulmonaires et systémiques, ce qui crée la congestion ; un débit cardiaque bas réduit la perfusion des organes.","nom":"Examen de la congestion et de la perfusion, puis profil clinique","pourquoi_ce_choix":"La ligne directrice classe le patient en profils chaud ou froid, humide ou sec, et elle distingue quatre présentations : décompensation, œdème pulmonaire aigu, insuffisance ventriculaire droite isolée et choc cardiogénique ; chacune a son traitement.","principe":"On recherche des crépitants, une turgescence jugulaire, un reflux hépato-jugulaire et des œdèmes, puis on juge la perfusion par la température des extrémités, la diurèse et la conscience.","rang":1,"recherche":"Il recherche une orthopnée, une fréquence respiratoire supérieure à 25 par minute, des crépitants, une turgescence jugulaire, des œdèmes et des extrémités froides.","src":[{"id":"R-ESC-IC","loc":"§ 11.2 et Table 21","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"La distension des cavités cardiaques libère des peptides natriurétiques ; un syndrome coronarien aigu ou une arythmie peut déclencher la décompensation.","nom":"ECG, peptides natriurétiques, troponine et biologie","pourquoi_ce_choix":"Des peptides natriurétiques normaux ont une forte valeur prédictive négative ; la troponine et l’ECG excluent un syndrome coronarien aigu, cause à traiter tout de suite.","principe":"On enregistre un ECG, on dose les peptides natriurétiques, la troponine, la créatinine, les électrolytes et la glycémie, et on mesure le lactate en cas d’hypoperfusion.","rang":2,"recherche":"Il recherche une ischémie, une arythmie, une élévation des peptides natriurétiques et une atteinte rénale ou métabolique.","src":[{"id":"R-ESC-IC","loc":"§ 11.1, Table 20","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une dysfonction ventriculaire, une valvulopathie aiguë ou une tamponnade expliquent la défaillance et changent le traitement.","nom":"Échocardiographie","pourquoi_ce_choix":"La ligne directrice la recommande à l’admission, car sa valeur diagnostique est majeure : elle montre la congestion, la dysfonction cardiaque et les causes mécaniques.","principe":"Les ultrasons montrent la fonction des ventricules, les valves, le péricarde et les pressions de remplissage.","rang":3,"recherche":"Elle recherche une dysfonction ventriculaire, une cause mécanique aiguë ou une tamponnade.","src":[{"id":"R-ESC-IC","loc":"§ 11.1, Table 20","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"insuffisance-cardiaque-aigue","label":"Insuffisance cardiaque aiguë","pec":{"mesures_generales":["L’équipe recherche et traite d’abord les causes du mnémonique CHAMPIT : syndrome coronarien aigu, urgence hypertensive, arythmie, cause mécanique aiguë, embolie pulmonaire, infection et tamponnade.","L’oxygène se donne si la saturation est inférieure à 90 %, et non en routine ; une ventilation non invasive se discute si la fréquence respiratoire dépasse 25 par minute ou si la saturation reste inférieure à 90 %.","Une prophylaxie de la thrombose veineuse se donne au patient qui n’est pas déjà anticoagulé ; les opiacés ne se donnent pas en routine."],"moyens_specifiques":[{"dose_ref":null,"limites":"Il expose à l’hypokaliémie, à l’hypovolémie et à une baisse transitoire de la fonction rénale, ce qui impose une surveillance des électrolytes et de la créatinine.","mecanisme":"La rétention de sel et d’eau par le rein augmente les pressions de remplissage et provoque la congestion.","pourquoi_ce_choix":"C’est le traitement de base de la congestion, quel que soit le profil de perfusion, avec une recommandation de classe I.","principe":"Un diurétique de l’anse intraveineux augmente l’excrétion de sodium et d’eau par le rein.","src":[{"id":"R-ESC-IC","loc":"§ 11.3.3, Figure 13","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le diurétique de l’anse intraveineux se recommande chez tout patient congestif ; un diurétique thiazidique peut s’y ajouter en cas de résistance. La diurèse et la natriurèse guident la dose. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Il provoque une hypotension et ne se donne pas au patient hypotendu ; ses autres contre-indications restent À vérifier dans la ligne directrice.","mecanisme":"Dans l’œdème pulmonaire aigu avec une pression élevée, la postcharge élevée empêche le ventricule gauche de se vider.","pourquoi_ce_choix":"Il soulage vite la congestion pulmonaire du patient hypertendu, avec une recommandation de faible niveau.","principe":"Un vasodilatateur intraveineux diminue la postcharge et la précharge, ce qui baisse les pressions de remplissage.","src":[{"id":"R-ESC-IC","loc":"§ 11.3.4 ; Figure 8","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un vasodilatateur intraveineux s’envisage si la pression systolique dépasse 110 mmHg. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à traiter la cause déclenchante, à soulager la congestion, à rétablir l’oxygénation et à préserver la perfusion des organes."},"src":[{"id":"R-ESC-IC","loc":"§ 11.1 à 11.3","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-dyspnee-congestive","urg-dyspnee-sifflante"]},"insuffisance-renale-aigue":{"bloquant":true,"confirmation":"L’insuffisance rénale aiguë se confirme par une hausse de la créatinine sérique ou par une oligurie selon les critères de stade ; la cause se précise par l’examen, l’échographie et l’analyse d’urine.","exam":{"lignes":[{"mecanisme":"La baisse brutale de la filtration glomérulaire fait monter la créatinine sérique et diminuer la diurèse.","nom":"Créatinine sérique et diurèse, avec stade selon KDIGO repris par l’ERBP","pourquoi_ce_choix":"La position européenne recommande de prendre en compte les deux critères et de choisir comme référence la créatinine d’admission de l’épisode ; le stade 1 commence à une hausse de 1,5 fois la référence ou à une diurèse inférieure à 0,5 millilitre par kilogramme et par heure pendant 6 heures.","principe":"On compare la créatinine à la première valeur de l’épisode et on mesure la diurèse horaire, rapportée au poids idéal.","rang":1,"recherche":"Il recherche une hausse de la créatinine, une oligurie et le stade de gravité.","src":[{"id":"R-ERBP-IRA","loc":"Recommendations 1.1.1, 1.1.2 et 1.1.2b","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une insuffisance rénale aiguë naît d’un défaut de perfusion, d’un obstacle sur les voies urinaires ou d’une atteinte du rein lui-même.","nom":"Recherche de la cause : hypovolémie, obstacle, bas débit, néphrotoxiques","pourquoi_ce_choix":"La position européenne exige au minimum de rechercher une hypovolémie, une cause post-rénale, un bas débit cardiaque, un néphrotoxique, une glomérulonéphrite aiguë et une micro-angiopathie.","principe":"On évalue la volémie, on recherche un globe vésical et une dilatation des voies urinaires, on revoit les médicaments et on analyse l’urine.","rang":2,"recherche":"Il recherche une déshydratation, un globe vésical, une insuffisance cardiaque, un anti-inflammatoire non stéroïdien ou un aminoside, une protéinurie ou une hématurie.","src":[{"id":"R-ERBP-IRA","loc":"Recommendation 1.1.3 ; Recommendation 1.2.1","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Le rein défaillant n’élimine plus le potassium ni les acides, et l’hyperkaliémie expose aux arythmies.","nom":"Kaliémie, gaz du sang et ECG","pourquoi_ce_choix":"Ces examens repèrent les complications qui menacent la vie et qui imposent un traitement immédiat ou une épuration extrarénale.","principe":"On dose le potassium, on mesure le pH et le bicarbonate, et on enregistre un ECG.","rang":3,"recherche":"Il recherche une hyperkaliémie, une acidose métabolique et des ondes T amples et pointues.","src":[{"id":"R-ERC-SPEC","loc":"Hyperkalaemia","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"insuffisance-renale-aigue","label":"Insuffisance rénale aiguë","pec":{"mesures_generales":["Les néphrotoxiques s’arrêtent ou s’adaptent à la fonction rénale : anti-inflammatoires non stéroïdiens, aminosides, amphotéricine B, fortes doses de diurétiques de l’anse, aciclovir et foscarnet.","Un obstacle sur les voies urinaires se lève, par exemple par une sonde vésicale devant un globe.","La créatinine et la diurèse se surveillent de près chez tout patient à risque."],"moyens_specifiques":[{"dose_ref":null,"limites":"Un excès de liquide aggrave la surcharge ; le soluté salé isotonique peut provoquer une acidose métabolique.","mecanisme":"L’hypovolémie diminue la perfusion du rein et la filtration glomérulaire.","pourquoi_ce_choix":"La position européenne le recommande en première intention chez le patient à risque d’insuffisance rénale aiguë, avec un grade 1B.","principe":"Un remplissage intraveineux par des cristalloïdes isotoniques restaure le volume circulant et la perfusion rénale.","src":[{"id":"R-ERBP-IRA","loc":"Recommendation 2.1.1 et Rationale","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"En l’absence de choc hémorragique, les cristalloïdes isotoniques se préfèrent aux colloïdes, albumine ou amidons. Les volumes restent À vérifier selon l’état clinique.","type":"pharmaco"},{"dose_ref":null,"limites":"La dopamine n’améliore pas le pronostic de l’insuffisance rénale aiguë, et les diurétiques ne préviennent ni ne traitent l’atteinte rénale.","mecanisme":"Dans le choc par vasodilatation, la pression de perfusion du rein reste basse malgré un remplissage suffisant.","pourquoi_ce_choix":"La pression de perfusion compte plus que le débit sanguin rénal, et le vasopresseur agit tout de suite, de façon réversible, sans surcharge.","principe":"Un vasopresseur restaure la pression de perfusion rénale.","src":[{"id":"R-ERBP-IRA","loc":"Recommendation 2.1.2 et Rationale ; diuretics","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un vasopresseur se recommande chez le patient en choc par vasodilatation déjà rempli ; la noradrénaline se préfère à la dopamine, et la vasopressine est une alternative. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à corriger la cause, à rétablir la perfusion rénale, à éviter les néphrotoxiques et à traiter les complications."},"src":[{"id":"R-ERBP-IRA","loc":"Recommendations 1 et 2","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-oligurie"]},"meningite-bacterienne":{"bloquant":true,"confirmation":"La méningite bactérienne se confirme par un liquide cérébrospinal inflammatoire où l’examen direct, la culture ou la PCR identifie une bactérie ; les hémocultures peuvent l’identifier si la ponction est retardée.","exam":{"lignes":[{"mecanisme":"Les bactéries envahissent l’espace sous-arachnoïdien et y provoquent une inflammation qui modifie le liquide cérébrospinal.","nom":"Ponction lombaire et analyse du liquide cérébrospinal","pourquoi_ce_choix":"Elle seule confirme la méningite bactérienne et identifie le germe, alors que les signes cliniques, comme la raideur de nuque ou le signe de Kernig, ont une précision diagnostique faible.","precautions":"Une imagerie cérébrale précède la ponction seulement en cas de déficit focal (hors paralysie d’un nerf crânien), de crise d’épilepsie récente, de score de Glasgow inférieur à 10 ou d’immunodépression sévère ; si la ponction est retardée, l’antibiotique commence avant.","principe":"La ponction lombaire prélève ce liquide ; sa cellularité, son glucose, ses protéines, son lactate, la coloration de Gram, la culture et la PCR montrent l’inflammation et identifient le germe.","rang":1,"recherche":"Elle recherche une hypercellularité du liquide et le germe à l’examen direct, en culture ou par PCR.","src":[{"id":"R-ESCMID-MEN","loc":"Key Questions 1 à 3 ; Imaging before lumbar puncture","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les bactéries responsables de la méningite passent souvent dans le sang.","nom":"Hémocultures avant la première dose d’antibiotique","pourquoi_ce_choix":"Elles identifient le germe quand la ponction lombaire est retardée ou contre-indiquée ; leur rendement baisse après le début de l’antibiotique, d’où leur prélèvement avant la première dose.","principe":"Les hémocultures cultivent ces bactéries et donnent leur sensibilité aux antibiotiques.","rang":2,"recherche":"Elles recherchent la bactérie et sa sensibilité aux antibiotiques.","src":[{"id":"R-ESCMID-MEN","loc":"Key Question 2, Blood cultures, recommandation de grade A","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"meningite-bacterienne","label":"Méningite bactérienne","pec":{"mesures_generales":["L’antibiotique commence au plus tard une heure après l’arrivée, et immédiatement dès la suspicion si la ponction lombaire est retardée.","Les contacts de la même maison et les autres contacts proches d’une méningite à méningocoque reçoivent une antibioprophylaxie par ceftriaxone, ciprofloxacine ou rifampicine."],"moyens_specifiques":[{"dose_ref":null,"limites":"La résistance du pneumocoque varie beaucoup entre les pays européens, et la situation suisse reste À vérifier ; le traitement s’adapte ensuite au germe et à son antibiogramme.","mecanisme":"Le pneumocoque, le méningocoque et, chez certains patients, Listeria se multiplient dans le liquide cérébrospinal, et le retard de traitement aggrave le pronostic.","pourquoi_ce_choix":"Ce schéma couvre les germes habituels de l’adulte selon l’âge et la résistance locale ; sans germe identifié, le schéma empirique se poursuit au moins deux semaines.","principe":"On tue les germes probables par un antibiotique intraveineux qui atteint les méninges, choisi selon l’âge, le terrain et la résistance locale.","src":[{"id":"R-ESCMID-MEN","loc":"Key Question 5, Table 4.1 et Table 4.2","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’adulte reçoit une céphalosporine de troisième génération (ceftriaxone ou céfotaxime) ; l’amoxicilline s’y ajoute après 50 ans ou en cas d’immunodépression pour couvrir Listeria, et la vancomycine ou la rifampicine s’y ajoute si le pneumocoque risque d’être moins sensible. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle s’arrête si la méningite n’est pas bactérienne, ou si le germe n’est ni Haemophilus influenzae ni le pneumocoque ; elle n’est pas recommandée chez le nouveau-né.","mecanisme":"L’inflammation intense de l’espace sous-arachnoïdien contribue aux décès et aux séquelles neurologiques, dont la surdité.","pourquoi_ce_choix":"La ligne directrice la recommande fortement en s’appuyant sur une méta-analyse Cochrane favorable.","principe":"On freine cette inflammation par un corticoïde donné en même temps que la première dose d’antibiotique.","src":[{"id":"R-ESCMID-MEN","loc":"Key Question 6, Subquestions 6.1 et 6.2","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La dexaméthasone se donne à tout adulte et à tout enfant atteint de méningite bactérienne aiguë dans les pays à revenu élevé, avec la première dose d’antibiotique ou au plus tard 4 heures après. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à stériliser le liquide cérébrospinal le plus vite possible et à limiter l’inflammation qui lèse le cerveau."},"src":[{"id":"R-ESCMID-MEN","loc":"Key Questions 1 à 9","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-fievre-meninge"]},"neuroborreliose":{"bloquant":false,"confirmation":"La neuroborréliose est certaine si le liquide cérébrospinal inflammatoire montre une synthèse intrathécale d’anticorps spécifiques ou une PCR ou une culture positive.","exam":{"lignes":[{"mecanisme":"La bactérie Borrelia, transmise par une tique, peut atteindre les racines nerveuses et les nerfs crâniens.","nom":"Sérologie de Borrelia (test immuno-enzymatique puis immunoblot)","pourquoi_ce_choix":"C’est un examen sanguin simple que la ligne directrice sur la paralysie faciale exige ; il se demande en cas de suspicion clinique suffisante.","precautions":"La sérologie peut rester négative au tout début de la maladie.","principe":"L’organisme produit des anticorps contre Borrelia : le test immuno-enzymatique les dépiste, et l’immunoblot les confirme.","rang":1,"recherche":"Elle recherche des anticorps IgM et IgG contre Borrelia dans le sang.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5 Laboruntersuchungen","lu_le":"2026-10-17"},{"id":"R-DGN-NB","loc":"Objectifs ; § 3.3 ; § 3.10","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Chez l’enfant, la ponction lombaire est obligatoire devant une paralysie faciale périphérique.","mecanisme":"L’infection du système nerveux déclenche une réaction inflammatoire dans le liquide cérébrospinal.","nom":"Ponction lombaire avec index d’anticorps spécifiques","pourquoi_ce_choix":"Elle seule rend le diagnostic probable ou certain, ce qui fait choisir l’antibiotique et renoncer aux corticoïdes.","principe":"La ponction montre l’inflammation, et l’index d’anticorps prouve que les anticorps se forment dans le système nerveux lui-même.","rang":2,"recherche":"Elle recherche une inflammation du liquide cérébrospinal, une rupture de la barrière hémato-encéphalique et une synthèse intrathécale d’anticorps contre Borrelia.","src":[{"id":"R-DGN-NB","loc":"§ 3.2 ; § 3.4 ; § 3.10, critères diagnostiques ; § 5.2.4","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"neuroborreliose","label":"Neuroborréliose (maladie de Lyme)","pec":{"mesures_generales":["L’efficacité du traitement se juge sur l’évolution clinique.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les contre-indications de chaque antibiotique restent À vérifier dans l’information professionnelle suisse.","mecanisme":"Une infection bactérienne entretient l’atteinte du nerf.","pourquoi_ce_choix":"La doxycycline orale est aussi efficace que les bêtalactamines intraveineuses, avec la même tolérance ; le choix tient compte des allergies, de la grossesse et du mode d’administration. La limite d’âge de 8 ans pour la doxycycline chez l’enfant est levée.","principe":"Un antibiotique élimine la bactérie.","src":[{"id":"R-DGN-NB","loc":"Statements 4 et 5 ; recommandations 14 et 24 ; durée","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une antibiothérapie par doxycycline, ceftriaxone, céfotaxime ou pénicilline G dure 14 jours dans la forme précoce. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Cette règle ne vaut que si le diagnostic est probable ou certain selon les critères du liquide cérébrospinal.","mecanisme":"La paralysie vient ici d’une infection, et non d’une inflammation idiopathique.","pourquoi_ce_choix":"La ligne directrice ne recommande pas d’ajouter des corticoïdes quand la neuroborréliose est probable ou certaine.","principe":"On traite la cause par l’antibiotique, sans ajouter de traitement contre l’inflammation.","src":[{"id":"R-DGN-NB","loc":"§ 5.2.4, recommandation 15","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Aucun corticoïde n’est ajouté à l’antibiotique.","type":"pharmaco"}],"objectif":"Le traitement vise à éradiquer Borrelia et à obtenir la récupération du nerf, qui est presque toujours bonne."},"src":[{"id":"R-DGN-NB","loc":"§ 3.10 ; § 5","lu_le":"2026-10-17"},{"id":"R-DGN-BELL","loc":"§ 2.1 ; § 2.6","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site4-mastoidien"]},"otite-moyenne-compliquee":{"bloquant":false,"confirmation":"Le diagnostic repose sur l’otoscopie et l’examen ORL.","exam":{"lignes":[{"mecanisme":"Une infection de l’oreille moyenne peut atteindre le nerf facial qui longe la paroi de la caisse du tympan.","nom":"Otoscopie","pourquoi_ce_choix":"Elle est simple, immédiate et fait partie de tout examen d’une paralysie faciale périphérique.","principe":"L’otoscopie montre l’inflammation du tympan, un écoulement ou un cholestéatome.","rang":1,"recherche":"Elle recherche une otite moyenne aiguë ou chronique et un cholestéatome.","src":[{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"},{"id":"R-DGN-BELL","loc":"§ 2.1 Tabelle 1","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’infection peut s’étendre à la mastoïde et toucher l’audition.","nom":"Examen ORL spécialisé","pourquoi_ce_choix":"La ligne directrice le demande devant toute anomalie de l’oreille, de la mastoïde, du tympan ou de l’audition.","principe":"Le spécialiste examine l’oreille moyenne, la mastoïde et le tympan, et il teste l’audition.","rang":2,"recherche":"Il évalue l’oreille moyenne, la mastoïde, le tympan et l’audition.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5, dernier alinéa","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Une infection grave peut détruire l’os et découvrir le nerf.","nom":"Imagerie du rocher","pourquoi_ce_choix":"L’IRM est indiquée devant un processus du rocher ; le choix entre scanner et IRM reste À vérifier.","principe":"L’imagerie montre une mastoïdite ou une destruction osseuse.","rang":3,"recherche":"Elle recherche une mastoïdite ou une destruction osseuse.","src":[{"id":"R-DGN-BELL","loc":"§ 2.4 Bildgebung","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"otite-moyenne-compliquee","label":"Otite moyenne compliquée de paralysie faciale","pec":{"mesures_generales":["Le patient est adressé à un ORL.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"Les limites et les contre-indications restent À vérifier dans une source suisse ou européenne.","mecanisme":"L’infection et l’inflammation de l’oreille moyenne compriment le nerf.","pourquoi_ce_choix":"Le choix entre ces moyens reste À vérifier dans une source suisse ou européenne.","principe":"On contrôle l’infection et l’on draine l’oreille moyenne.","statut":"À vérifier","texte":"L’ORL choisit entre antibiothérapie, paracentèse et chirurgie de la mastoïde.","type":"autre"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à contrôler l’infection de l’oreille moyenne et à décomprimer le nerf."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1, 2.5","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2, 3","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site3-tympanique"]},"pancreatite-aigue":{"bloquant":true,"confirmation":"La pancréatite aiguë se confirme quand deux critères sur trois sont présents : une douleur épigastrique typique en ceinture qui irradie vers le dos, une lipase d’au moins trois fois la normale et une imagerie typique.","exam":{"lignes":[{"mecanisme":"Le pancréas enflammé libère ses enzymes digestives dans le sang.","nom":"Lipase sérique","pourquoi_ce_choix":"Une lipase d’au moins trois fois la limite supérieure de la normale est l’un des trois critères du diagnostic, avec la douleur typique et l’imagerie typique ; deux critères sur trois suffisent.","principe":"La prise de sang mesure la lipase, une enzyme fabriquée par le pancréas.","rang":1,"recherche":"Il recherche une lipase d’au moins trois fois la normale.","src":[{"id":"R-DGVS-PAN","loc":"1.6.1","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Un calcul de la vésicule qui bloque la sortie du canal pancréatique est la cause la plus fréquente.","nom":"Échographie abdominale et bilan du foie à l’admission","pourquoi_ce_choix":"La ligne directrice les demande à l’admission pour trouver une cause biliaire, qui change la prise en charge ; le scanner n’est pas nécessaire au diagnostic quand la douleur et la lipase sont typiques.","principe":"L’échographie montre les calculs de la vésicule et la dilatation des voies biliaires ; la prise de sang mesure la bilirubine, les phosphatases alcalines, les transaminases, les triglycérides et le calcium.","rang":2,"recherche":"Il recherche des calculs, une dilatation des voies biliaires, une cholestase, une hypertriglycéridémie ou une hypercalcémie.","src":[{"id":"R-DGVS-PAN","loc":"1.6.2 et 3.1.2","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"La gravité dépend d’une défaillance d’organe, passagère en moins de 48 heures ou persistante au-delà.","nom":"Évaluation de la gravité à l’admission et à 48 heures","pourquoi_ce_choix":"Une défaillance qui persiste au-delà de 48 heures définit la forme grave ; ces critères désignent les patients qui vont en soins intensifs.","principe":"On recherche un syndrome de réponse inflammatoire systémique, une défaillance d’organe, et on mesure l’hématocrite, l’urée et la créatinine.","rang":3,"recherche":"Il recherche une défaillance circulatoire, respiratoire ou rénale, un SIRS, un hématocrite ou une urée élevés.","src":[{"id":"R-DGVS-PAN","loc":"2.1.2 ; 4.4.1","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"pancreatite-aigue","label":"Pancréatite aiguë","pec":{"mesures_generales":["Le patient qui présente des critères de gravité est surveillé en soins intensifs.","Dans une forme légère, il remange par la bouche dès le premier jour ; il ne reçoit pas d’antibiotique préventif.","Après une pancréatite biliaire légère, la vésicule s’enlève pendant la même hospitalisation."],"moyens_specifiques":[{"dose_ref":null,"limites":"La pression veineuse centrale ne guide pas le remplissage ; l’insuffisance cardiaque ou rénale réduit les volumes.","mecanisme":"L’inflammation fait fuir le liquide hors des vaisseaux et réduit la perfusion du pancréas et des autres organes.","pourquoi_ce_choix":"La ligne directrice relie le volume perfusé à la mortalité : un remplissage trop faible et un remplissage trop abondant sont tous deux nuisibles.","principe":"On rétablit le volume circulant par un remplissage intraveineux contrôlé, commencé dès le diagnostic.","src":[{"id":"R-DGVS-PAN","loc":"4.1.1 à 4.1.5","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un remplissage contrôlé, surtout par du Ringer lactate, commence dès le diagnostic et s’ajuste à l’hémodynamique, à l’urée et à l’hématocrite ; les volumes restent À vérifier.","type":"pharmaco"},{"dose_ref":null,"limites":"Ils exposent à l’iléus et à la dépression respiratoire, ce qui impose une surveillance.","mecanisme":"La douleur de la pancréatite est intense et gêne la respiration.","pourquoi_ce_choix":"La ligne directrice préfère ces opioïdes pour la douleur sévère de la pancréatite.","principe":"Un opioïde soulage la douleur sévère.","src":[{"id":"R-DGVS-PAN","loc":"4.2.1 et 4.2.2","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Un opioïde, de préférence la buprénorphine ou la péthidine, traite la douleur sévère. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Une intolérance digestive ou un iléus peuvent la limiter.","mecanisme":"Le jeûne prolongé abîme la barrière de l’intestin et favorise l’infection de la nécrose.","pourquoi_ce_choix":"La nutrition entérale réduit les complications infectieuses par rapport à la nutrition intraveineuse.","principe":"On garde l’intestin actif par une nutrition par la bouche ou par sonde.","src":[{"id":"R-DGVS-PAN","loc":"5.3.1 à 5.3.3","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Dans une forme grave, une nutrition entérale précoce remplace la nutrition parentérale.","type":"autre"},{"dose_ref":null,"limites":"Elle peut elle-même provoquer une pancréatite et des saignements.","mecanisme":"Un calcul bloqué dans le canal biliaire entretient l’obstruction et peut infecter la bile.","pourquoi_ce_choix":"Elle traite la cause quand la bile reste bloquée ou infectée.","principe":"La CPRE avec sphinctérotomie ouvre la sortie du canal biliaire et extrait le calcul.","src":[{"id":"R-DGVS-PAN","loc":"6.2.1 à 6.2.4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une CPRE avec sphinctérotomie se fait en urgence en cas de cholangite, et rapidement en cas d’obstruction biliaire ; elle ne se fait pas dans une pancréatite biliaire légère sans cholangite ni obstruction.","type":"interventionnel"}],"objectif":"Le traitement vise à maintenir la perfusion des organes, à calmer la douleur, à nourrir le patient et à traiter la cause biliaire."},"src":[{"id":"R-DGVS-PAN","loc":"chapitres 1 à 6","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-douleur-abdominale-aigue"]},"pneumothorax-sous-tension":{"bloquant":true,"confirmation":"Le diagnostic est clinique chez le patient instable : un pneumothorax avec hypotension ou arrêt cardiaque se traite comme un pneumothorax sous tension sans attendre l’imagerie.","exam":{"lignes":[{"mecanisme":"L’air pénètre dans la plèvre sans pouvoir en sortir ; la pression monte, refoule le médiastin et écrase le retour veineux vers le cœur.","nom":"Examen clinique au lit : signes de pneumothorax avec retentissement hémodynamique","pourquoi_ce_choix":"La ligne directrice fonde le diagnostic du patient instable sur l’examen clinique ou l’échographie au lit, sans attendre de radiographie, car la décompression ne peut pas attendre.","principe":"L’examen associe une détresse respiratoire, une hypoxie, un murmure vésiculaire aboli d’un côté, un emphysème sous-cutané, une déviation de la trachée et des jugulaires turgescentes à une hypotension.","rang":1,"recherche":"Il recherche l’asymétrie de l’auscultation, la déviation de la trachée, la turgescence des jugulaires et l’hypotension.","src":[{"id":"R-ERC-SPEC","loc":"Tension pneumothorax, Diagnosis","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’air interposé entre les deux feuillets de la plèvre empêche leur glissement l’un contre l’autre à chaque respiration.","nom":"Échographie pleuropulmonaire au lit","pourquoi_ce_choix":"Elle se fait au lit en quelques minutes, même pendant la réanimation, et la ligne directrice l’admet avec l’examen clinique pour décider de la décompression.","principe":"La sonde posée sur le thorax montre si les feuillets de la plèvre glissent ou non ; l’absence de glissement d’un côté évoque le pneumothorax.","rang":2,"recherche":"Elle recherche les signes échographiques d’un pneumothorax du côté suspect.","src":[{"id":"R-ERC-SPEC","loc":"Tension pneumothorax, Diagnosis","lu_le":"2026-10-17"}],"statut":"À vérifier"}],"reference":null},"id":"pneumothorax-sous-tension","label":"Pneumothorax sous tension","pec":{"mesures_generales":["Le patient reçoit de l’oxygène et reste sous surveillance continue.","La ventilation en pression positive peut transformer un pneumothorax simple en pneumothorax sous tension : l’équipe y pense chez tout patient ventilé qui se dégrade."],"moyens_specifiques":[{"dose_ref":null,"limites":"Une aiguille trop courte échoue souvent à cause de l’épaisseur de la paroi, et il faut une longueur d’au moins 7 cm ; la canule se coude ou se bouche facilement.","mecanisme":"La pression de l’air piégé dans la plèvre comprime le médiastin et bloque le retour du sang veineux vers le cœur.","pourquoi_ce_choix":"Elle est rapide et à la portée de la plupart des équipes de secours ; ce site a le taux d’échec prévu le plus bas, comparé au 2e espace intercostal sur la ligne médioclaviculaire.","principe":"On ouvre une voie de sortie à l’air en ponctionnant la plèvre avec une aiguille.","src":[{"id":"R-ERC-SPEC","loc":"Tension pneumothorax, Treatment recommendations, Needle decompression","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La décompression à l’aiguille, au 4e ou 5e espace intercostal sur la ligne axillaire antérieure, sert de pont rapide ; une thoracostomie ouverte ou un drain thoracique doit la suivre.","type":"interventionnel"},{"dose_ref":null,"limites":"Elle exige une compétence et un matériel adaptés ; chez le patient conscient, l’analgésie et les complications propres du geste restent À vérifier.","mecanisme":"L’air continue de fuir du poumon vers la plèvre tant que la brèche reste ouverte.","pourquoi_ce_choix":"Elle décomprime plus sûrement que l’aiguille, qui échoue souvent ; la ligne directrice la place en premier quand l’expertise est disponible.","principe":"On ouvre largement la plèvre par une incision de la paroi, puis un drain thoracique évacue l’air de façon durable.","src":[{"id":"R-ERC-SPEC","loc":"Tension pneumothorax, Diagnosis et Treatment recommendations","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La thoracostomie ouverte se fait immédiatement en cas d’arrêt cardiaque ou d’hypotension sévère si l’équipe a l’expertise, et un drain thoracique la complète.","type":"chirurgie"}],"objectif":"Le traitement vise à évacuer immédiatement l’air sous pression pour rétablir le retour veineux et l’oxygénation."},"src":[{"id":"R-ERC-SPEC","loc":"Tension pneumothorax","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-douleur-thoracique","urg-choc"]},"polytraumatisme":{"bloquant":true,"confirmation":"Le bilan des lésions se confirme par l’examen primaire, l’échographie ciblée et le scanner corps entier.","exam":{"lignes":[{"mecanisme":"Une hémorragie externe massive, une obstruction des voies aériennes, un pneumothorax sous tension, un choc hémorragique ou une lésion cérébrale tuent en quelques minutes, dans cet ordre de rapidité.","nom":"Bilan primaire selon le schéma xABCDE","pourquoi_ce_choix":"La ligne directrice allemande organise l’accueil selon ce schéma et fixe les critères qui activent l’équipe de déchocage ; la ligne directrice européenne ajoute la lettre de l’hémorragie critique avant les voies aériennes.","principe":"On contrôle d’abord une hémorragie externe massive, puis on examine les voies aériennes, la respiration, la circulation, l’état neurologique et l’exposition du corps entier en protégeant la température.","rang":1,"recherche":"Il recherche une saturation inférieure à 90 %, une fréquence respiratoire inférieure à 10 ou supérieure à 29 par minute, une pression systolique inférieure à 90 mmHg, une fréquence cardiaque supérieure à 120 par minute, un indice de choc supérieur à 0,9, un score de Glasgow de 12 ou moins et une température inférieure à 35 °C.","src":[{"id":"R-AWMF-POLY","loc":"Empfehlung 2.2.4","lu_le":"2026-10-17"},{"id":"R-EU-SAIGNEMENT","loc":"Recommendation 5, Rationale","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Un saignement dans le péritoine, la plèvre ou le péricarde forme un épanchement liquidien que l’échographie voit.","nom":"Échographie ciblée du traumatisé (FAST)","pourquoi_ce_choix":"Elle se fait au lit, sans déplacer le patient instable ; un épanchement chez un patient en choc oriente vers un geste immédiat d’arrêt du saignement.","principe":"La sonde explore le péricarde, les espaces autour du foie, de la rate et de la vessie, puis les plèvres.","rang":2,"recherche":"Elle recherche un hémopéritoine, un hémothorax, un pneumothorax ou un hémopéricarde.","src":[{"id":"R-EU-SAIGNEMENT","loc":"Recommendation 8","lu_le":"2026-10-17"},{"id":"R-AWMF-POLY","loc":"Empfehlung 2.2.4","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les lésions du crâne, du rachis, du thorax, de l’abdomen et du bassin coexistent souvent, et certaines ne donnent pas de signe clinique.","nom":"Scanner corps entier injecté","pourquoi_ce_choix":"La ligne directrice allemande demande un scanner corps entier rapide quand aucun geste immédiat n’est nécessaire et que la pression systolique ne descend pas sous 60 mmHg ; la ligne directrice européenne le recommande pour trouver la source du saignement.","principe":"Le scanner explore en une seule acquisition le corps du crâne au bassin avec un produit de contraste.","rang":3,"recherche":"Il recherche les lésions et la source de l’hémorragie.","src":[{"id":"R-AWMF-POLY","loc":"Empfehlung 2.5.5","lu_le":"2026-10-17"},{"id":"R-EU-SAIGNEMENT","loc":"Recommendation 8","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"polytraumatisme","label":"Polytraumatisme","pec":{"mesures_generales":["Le patient grave part directement vers un centre de traumatologie adapté, et le délai entre le traumatisme et le contrôle du saignement doit rester le plus court possible.","Les voies aériennes se sécurisent sans délai en cas d’obstruction, de score de Glasgow de 8 ou moins, d’hypoventilation ou d’hypoxémie.","La perte de chaleur se limite tôt, et le patient hypothermique se réchauffe.","L’hémoglobine, le lactate et la coagulation se mesurent tôt et de façon répétée, car une première hémoglobine normale peut masquer un saignement."],"moyens_specifiques":[{"dose_ref":null,"limites":"Un garrot pas assez serré reste inefficace, et même des équipes entraînées posent mal une partie des ceintures pelviennes.","mecanisme":"Une hémorragie externe d’un membre peut tuer avant l’arrivée à l’hôpital.","pourquoi_ce_choix":"Les deux lignes directrices recommandent ce schéma par étapes, car la compression locale suffit le plus souvent.","principe":"La compression locale écrase le vaisseau qui saigne ; le garrot interrompt le flux artériel en amont de la plaie.","src":[{"id":"R-AWMF-POLY","loc":"Empfehlung 1.1.9","lu_le":"2026-10-17"},{"id":"R-EU-SAIGNEMENT","loc":"Recommendations 2 et 20","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’hémorragie d’un membre se traite par compression manuelle, puis par pansement compressif, si possible avec un agent hémostatique, puis par garrot. Une ceinture pelvienne se pose devant une suspicion de fracture du bassin.","type":"autre"},{"dose_ref":null,"limites":"Elle est contre-indiquée en cas de traumatisme crânien ou médullaire, car le système nerveux lésé exige une pression de perfusion suffisante ; le Ringer lactate s’évite dans le traumatisme crânien grave.","mecanisme":"Le saignement fait chuter la pression artérielle ; un remplissage abondant dilue les facteurs de coagulation et entretient le saignement.","pourquoi_ce_choix":"La ligne directrice européenne recommande cette hypotension permissive, car elle réduit la mortalité par rapport au remplissage agressif, qui favorise la coagulopathie et les défaillances d’organes.","principe":"Une stratégie de remplissage restreint accepte une pression basse tant que le saignement n’est pas arrêté.","src":[{"id":"R-EU-SAIGNEMENT","loc":"Recommendations 13 à 15","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"En l’absence de traumatisme crânien, la pression systolique cible se situe entre 80 et 90 mmHg jusqu’à l’arrêt du saignement ; avec un traumatisme crânien grave, la pression artérielle moyenne reste d’au moins 80 mmHg. Les cristalloïdes se choisissent isotoniques, et la noradrénaline s’ajoute si la cible n’est pas atteinte. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"La ligne directrice européenne limite son indication aux 3 heures qui suivent le traumatisme ; la dose citée par les lignes directrices reste À vérifier dans l’information professionnelle suisse.","mecanisme":"Le traumatisme active la fibrinolyse, qui dissout les caillots et aggrave le saignement.","pourquoi_ce_choix":"Les deux lignes directrices le recommandent avec leur plus haut niveau de recommandation, et l’administration ne retarde aucun autre geste.","principe":"L’acide tranexamique bloque la fibrinolyse et stabilise les caillots.","src":[{"id":"R-EU-SAIGNEMENT","loc":"Recommendation 23","lu_le":"2026-10-17"},{"id":"R-AWMF-POLY","loc":"Empfehlung 2.4.20","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’acide tranexamique se donne le plus tôt possible, au mieux pendant le transport et dans les 3 heures qui suivent le traumatisme, au patient qui saigne ou qui risque de saigner, sans attendre un test viscoélastique. La posologie reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle exige une équipe chirurgicale et radiologique disponible ; le patient stable sans ces facteurs reçoit d’emblée la réparation définitive.","mecanisme":"Un saignement interne d’une cavité ne s’arrête pas par la compression externe.","pourquoi_ce_choix":"La ligne directrice européenne la recommande devant un choc hémorragique, un saignement persistant ou une coagulopathie, et aussi devant une hypothermie ou une acidose.","principe":"La chirurgie de contrôle des lésions arrête le saignement et la contamination par des gestes courts, puis la réparation définitive attend la stabilisation.","src":[{"id":"R-EU-SAIGNEMENT","loc":"Recommendations 6, 19 à 21","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le patient en choc hémorragique, avec un saignement persistant ou une coagulopathie, reçoit un geste immédiat d’arrêt du saignement et une chirurgie de contrôle des lésions ; le bassin instable se stabilise tôt, et l’embolisation ou le packing s’envisagent selon la source.","type":"chirurgie"}],"objectif":"Le traitement vise à arrêter le saignement, à assurer l’oxygénation et à prévenir la triade de l’hypothermie, de l’acidose et de la coagulopathie, en limitant le délai jusqu’au contrôle de l’hémorragie."},"src":[{"id":"R-AWMF-POLY","loc":"Die wichtigsten Empfehlungen auf einen Blick","lu_le":"2026-10-17"},{"id":"R-EU-SAIGNEMENT","loc":"Recommendations 1 à 24","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-traumatisme-grave"]},"sca":{"bloquant":true,"confirmation":"L’infarctus se confirme par des symptômes d’ischémie avec une élévation et une variation de la troponine ; un sus-décalage persistant du segment ST pose d’emblée le diagnostic de travail d’infarctus avec sus-décalage du ST (STEMI).","exam":{"lignes":[{"mecanisme":"L’occlusion aiguë d’une artère coronaire prive de sang une partie du myocarde, dont la souffrance modifie l’activité électrique en quelques minutes.","nom":"Électrocardiogramme à 12 dérivations dans les 10 minutes","pourquoi_ce_choix":"Il se fait au premier contact médical et trie à lui seul les patients vers une reperfusion immédiate ; la ligne directrice demande de l’enregistrer et de l’interpréter dans les 10 minutes.","precautions":"Un premier tracé non concluant n’exclut pas le diagnostic : un nouveau tracé se fait si les symptômes persistent ou reviennent, et des dérivations supplémentaires se font si une occlusion postérieure est suspectée.","principe":"L’électrocardiogramme enregistre cette activité électrique ; un sus-décalage persistant du segment ST, ou un équivalent, signale une occlusion coronaire en cours.","rang":1,"recherche":"Il recherche un sus-décalage du segment ST, un équivalent de sus-décalage ou d’autres signes d’ischémie.","src":[{"id":"R-ESC-SCA","loc":"§ 3.2, Recommendation Table 2 ; § 5.1","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"La nécrose des cellules du myocarde libère dans le sang des protéines de leur appareil contractile, dont la troponine.","nom":"Troponine cardiaque ultrasensible selon l’algorithme 0 h/1 h (ou 0 h/2 h)","pourquoi_ce_choix":"Quand l’ECG ne montre pas de sus-décalage, cet algorithme exclut l’infarctus avec une valeur prédictive négative supérieure à 99 % en une à deux heures ; il ne retarde jamais la reperfusion d’un sus-décalage.","principe":"Le dosage ultrasensible mesure la troponine à l’arrivée puis une heure (ou deux heures) plus tard ; le niveau et sa variation classent le patient en exclusion, observation ou confirmation de l’infarctus.","rang":2,"recherche":"Il recherche une élévation de la troponine et sa variation entre deux dosages.","src":[{"id":"R-ESC-SCA","loc":"§ 3.3.4 et 3.3.4.1, Figure 6","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"sca","label":"Syndrome coronarien aigu","pec":{"mesures_generales":["Le patient reste sous monitorage de l’ECG avec un défibrillateur à portée de main, car une arythmie grave peut survenir à tout moment.","L’oxygène se donne seulement si la saturation est inférieure à 90 % ; il n’est pas recommandé en routine au-dessus de 90 %.","Un opioïde intraveineux peut soulager la douleur, et un anxiolytique léger peut aider un patient très anxieux.","Le service de secours transfère le patient suspect de STEMI directement vers un centre d’angioplastie disponible 24 heures sur 24, sans passer par un hôpital qui n’en a pas."],"moyens_specifiques":[{"dose_ref":null,"limites":"Elle exige un centre de cardiologie interventionnelle ; si elle n’est pas possible dans les 120 minutes, la fibrinolyse la précède. Après 12 heures de symptômes, elle reste préférée à la fibrinolyse ; après 48 heures sans symptôme persistant, l’angioplastie de routine d’une artère occluse n’est plus recommandée.","mecanisme":"Un caillot formé sur une plaque d’athérome rompue bouche l’artère coronaire, et chaque minute d’occlusion étend la nécrose.","pourquoi_ce_choix":"À délai égal, elle réduit davantage que la fibrinolyse la mortalité, la récidive d’infarctus et l’AVC, et elle traite en même temps la lésion responsable.","principe":"On rouvre l’artère par un cathéter : un guide franchit le caillot, un ballonnet dilate la lésion et un stent la maintient ouverte.","src":[{"id":"R-ESC-SCA","loc":"§ 5.1 et 5.2.1 ; Recommendation Table 4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’intervention coronarienne percutanée primaire (angioplastie primaire) se fait si elle est possible dans les 120 minutes qui suivent le diagnostic à l’ECG. Un NSTE-ACS à très haut risque (choc, douleur réfractaire, arythmie grave, complication mécanique) reçoit une coronarographie immédiate ; une coronarographie dans les 24 heures s’envisage pour un NSTE-ACS à haut risque.","type":"interventionnel"},{"dose_ref":null,"limites":"Elle expose à l’hémorragie, et ses contre-indications précises restent À vérifier dans la ligne directrice. Si le sus-décalage ne diminue pas d’au moins 50 % dans les 60 à 90 minutes, une angioplastie de sauvetage s’impose.","mecanisme":"Le thrombus qui bouche l’artère coronaire contient un réseau de fibrine, et le myocarde d’aval meurt tant qu’il persiste.","pourquoi_ce_choix":"Elle se donne partout et vite, ce qui raccourcit l’ischémie quand le transfert est long ; la stratégie pharmaco-invasive prévoit ensuite une coronarographie dans les 2 à 24 heures.","principe":"On dissout la fibrine du caillot par un fibrinolytique injecté dans une veine, sans attendre un centre de cathétérisme.","src":[{"id":"R-ESC-SCA","loc":"§ 5.2.1 et 5.3 ; Recommendation Table 4","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La fibrinolyse se donne dans les 12 heures qui suivent le début des symptômes quand l’angioplastie primaire n’est pas possible dans les 120 minutes ; le patient part ensuite vers un centre d’angioplastie sans attendre les signes de reperfusion. Le produit et sa posologie restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Ils augmentent le risque hémorragique : un inhibiteur de la pompe à protons s’y ajoute si le risque d’hémorragie digestive est élevé, et le fondaparinux n’est pas recommandé lors de l’angioplastie primaire.","mecanisme":"Les plaquettes activées sur la plaque rompue et la cascade de la coagulation entretiennent et étendent le thrombus coronaire.","pourquoi_ce_choix":"La ligne directrice recommande ces trois traitements chez tout patient sans contre-indication ; elle propose le prasugrel chez le patient qui n’a pas encore reçu d’inhibiteur P2Y12 et qui part vers l’angioplastie.","principe":"On bloque l’agrégation des plaquettes par deux antiagrégants et la formation de fibrine par un anticoagulant injectable.","src":[{"id":"R-ESC-SCA","loc":"§ 6 ; Recommendation Table 5","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’aspirine, un inhibiteur du récepteur P2Y12 et un anticoagulant parentéral se donnent dès le diagnostic ; la double antiagrégation plaquettaire dure ensuite 12 mois, sauf risque hémorragique élevé. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"}],"objectif":"Le traitement vise à rouvrir au plus vite l’artère coronaire occluse pour limiter la nécrose du myocarde, puis à prévenir une nouvelle thrombose."},"src":[{"id":"R-ESC-SCA","loc":"§ 3 à 6","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-douleur-thoracique"]},"schwannome-vestibulaire":{"bloquant":false,"confirmation":"Le diagnostic repose sur l’IRM ; une confirmation histologique n’est pas toujours nécessaire.","exam":{"lignes":[],"reference":{"mecanisme":"Une tumeur bénigne de la gaine du nerf vestibulaire grossit lentement dans le méat acoustique interne et l’angle ponto-cérébelleux.","nom":"IRM du méat acoustique interne et de l’angle ponto-cérébelleux, T1 avec gadolinium","pourquoi_ce_choix":"C’est l’examen de référence de la ligne directrice européenne ; la même technique sert à la surveillance.","precautions":"Les précautions du gadolinium (insuffisance rénale, grossesse) restent À vérifier dans une source suisse ou européenne.","principe":"Le gadolinium rehausse la tumeur sur les séquences T1, ce qui montre sa taille et son extension.","recherche":"Elle montre la tumeur, sa taille et son extension dans le méat acoustique interne.","src":[{"id":"R-EANO-VS","loc":"Diagnostic Procedures, Imaging ; Follow-up","lu_le":"2026-10-17"}],"statut":"sourcé"}},"id":"schwannome-vestibulaire","label":"Schwannome vestibulaire","pec":{"mesures_generales":["Le dossier est discuté en réunion de concertation pluridisciplinaire, et une chirurgie se fait dans un centre à grand volume.","L’œil est protégé en cas de lagophtalmie."],"moyens_specifiques":[{"limites":"Elle suppose un suivi régulier ; une croissance ou de nouveaux symptômes imposent un traitement.","mecanisme":"Une petite tumeur bénigne peut rester stable longtemps.","pourquoi_ce_choix":"Elle évite les risques d’un traitement chez un patient peu symptomatique.","principe":"On surveille la croissance et l’audition, et l’on ne traite que si la tumeur progresse.","src":[{"id":"R-EANO-VS","loc":"Therapeutic Strategies, Observation ; Follow-up","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La tumeur est surveillée par IRM et audiométrie, chaque année pendant 5 ans.","type":"suivi"},{"limites":"Elle menace le nerf facial et l’audition ; le monitorage du nerf facial améliore le résultat, et l’opération se fait dans un centre à grand volume.","mecanisme":"Une grosse tumeur comprime le tronc cérébral et les nerfs voisins.","pourquoi_ce_choix":"C’est l’option de la grosse tumeur compressive, car la radiochirurgie ne convient qu’aux petits volumes.","principe":"On retire la tumeur, en totalité ou en partie, pour lever la compression.","src":[{"id":"R-EANO-VS","loc":"Abstract ; Surgery","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une exérèse chirurgicale est faite avec monitorage du nerf facial, suivie au besoin d’une radiothérapie ou d’une radiochirurgie.","type":"chirurgie"},{"limites":"Elle ne convient pas aux grosses tumeurs compressives, et la tumeur reste en place sous surveillance.","mecanisme":"Une petite tumeur ou un reste après chirurgie peut continuer de grossir.","pourquoi_ce_choix":"Elle évite une ouverture du crâne pour une petite tumeur ou une récidive après chirurgie.","principe":"Une irradiation très ciblée vise à arrêter la croissance de la tumeur sans l’enlever.","src":[{"id":"R-EANO-VS","loc":"Abstract ; Radiosurgery","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une radiochirurgie est proposée.","type":"interventionnel"}],"objectif":"Le traitement vise à contrôler la tumeur en préservant la fonction faciale et l’audition."},"src":[{"id":"R-EANO-VS","loc":"Abstract ; Diagnostic Procedures ; Therapeutic Strategies","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site2-genicule"]},"sepsis":{"bloquant":true,"confirmation":"Le sepsis est une dysfonction d’organe menaçant la vie, causée par une réponse dérégulée de l’hôte à une infection ; le choc septique en est une forme, avec une dysfonction circulatoire, cellulaire et métabolique qui augmente le risque de décès.","exam":{"lignes":[{"mecanisme":"L’infection déclenche une réponse dérégulée de l’hôte qui altère la perfusion des tissus, et les cellules mal oxygénées produisent du lactate.","nom":"Lactate sanguin","pourquoi_ce_choix":"La ligne directrice suggère de le mesurer chez tout adulte suspect de sepsis, car son niveau est lié à la mortalité ; elle déconseille le qSOFA comme seul outil de dépistage, car sa sensibilité est faible.","precautions":"Un lactate élevé s’interprète selon le contexte clinique, car d’autres causes que le sepsis l’augmentent.","principe":"Le dosage du lactate dans le sang mesure cette hypoperfusion ; avec le temps de recoloration capillaire, il aide à suivre la réanimation.","rang":1,"recherche":"Il recherche une élévation du lactate, signe d’hypoperfusion des tissus.","src":[{"id":"R-SSC-2021","loc":"Recommendations 2, 3 et 7 ; Screening and early treatment","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"Les bactéries passent du foyer infectieux dans le sang, ou restent enfermées dans un foyer collecté que l’antibiotique atteint mal.","nom":"Hémocultures et prélèvements du foyer, puis imagerie de la source","pourquoi_ce_choix":"Elles servent à adapter puis à réduire l’antibiothérapie, et à repérer vite un foyer qui exige un contrôle de la source ; elles ne doivent jamais retarder l’antibiotique.","principe":"Les cultures identifient le germe et sa sensibilité ; l’imagerie du foyer recherche une collection ou une obstruction à drainer.","rang":2,"recherche":"Elles recherchent le germe, sa sensibilité et un foyer qui demande un drainage.","src":[{"id":"R-SSC-2021","loc":"Recommendations 12 et 27, Rationale","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"sepsis","label":"Sepsis","pec":{"mesures_generales":["Le sepsis et le choc septique sont des urgences : le traitement et la réanimation commencent immédiatement.","Chez le patient en choc septique sous vasopresseur, la réanimation vise d’abord une pression artérielle moyenne de 65 mmHg.","Le temps de recoloration capillaire aide à guider le remplissage, avec les autres mesures de la perfusion."],"moyens_specifiques":[{"dose_ref":null,"limites":"Un traitement trop large chez un patient non infecté expose aux effets indésirables et aux résistances ; quand le sepsis est seulement possible et qu’il n’y a pas de choc, une évaluation rapide de 3 heures au plus précède la décision.","mecanisme":"La multiplication des bactéries entretient la réponse inflammatoire de l’hôte et la défaillance des organes.","pourquoi_ce_choix":"La ligne directrice émet une recommandation forte, car le risque de décès du choc septique est élevé et fortement lié au délai de l’antibiothérapie.","principe":"On tue les bactéries par une antibiothérapie intraveineuse à large spectre, choisie selon le foyer probable et l’écologie locale, puis adaptée au germe.","src":[{"id":"R-SSC-2021","loc":"Recommendations 12 et 13, Time to antibiotics","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’antibiothérapie se donne immédiatement, idéalement dans l’heure, en cas de choc septique possible ou de sepsis probable. Le choix des molécules et leurs posologies restent À vérifier dans une recommandation suisse et dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Le remplissage se guide sur des mesures répétées de la perfusion pour éviter la surcharge ; la ligne directrice déconseille la gélatine.","mecanisme":"La vasodilatation et la fuite capillaire diminuent le volume sanguin efficace et la perfusion des organes.","pourquoi_ce_choix":"La ligne directrice recommande les cristalloïdes en première ligne et suggère les solutés balancés, qu’une méta-analyse en réseau associe à une mortalité plus faible que le sérum physiologique.","principe":"On rétablit le volume circulant par des perfusions intraveineuses de cristalloïdes.","src":[{"id":"R-SSC-2021","loc":"Recommendations 5, 32, 33 et 36","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Les cristalloïdes sont le soluté de première ligne, de préférence des cristalloïdes balancés plutôt que le sérum physiologique ; le volume initial que suggère la ligne directrice pour les 3 premières heures reste À vérifier.","type":"pharmaco"},{"dose_ref":null,"limites":"Elle peut commencer par une veine périphérique, pour une courte durée, plutôt que d’attendre une voie centrale, et la pression artérielle se mesure de façon invasive dès que possible.","mecanisme":"La vasodilatation du choc septique fait chuter la pression artérielle malgré un remplissage suffisant.","pourquoi_ce_choix":"La ligne directrice la préfère aux autres vasopresseurs (dopamine, vasopressine, adrénaline) par une recommandation forte, et une cible de pression plus haute n’apporte pas de bénéfice.","principe":"On contracte les vaisseaux par un vasopresseur pour remonter la pression de perfusion des organes.","src":[{"id":"R-SSC-2021","loc":"Recommendations 6, 37, 43, 44 et 58","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"La noradrénaline est le vasopresseur de première ligne ; une corticothérapie intraveineuse s’ajoute si le besoin de vasopresseur persiste. Les posologies restent À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"dose_ref":null,"limites":"Le geste dépend du foyer et de l’état du patient ; le délai précis selon le foyer reste À vérifier.","mecanisme":"Un foyer collecté, nécrosé ou un matériel infecté entretient l’infection malgré l’antibiotique.","pourquoi_ce_choix":"La ligne directrice en fait une bonne pratique, car le contrôle de la source est un principe clé du traitement que l’antibiotique seul ne remplace pas.","principe":"On évacue ou on retire le foyer infecté : drainage, débridement ou ablation d’un dispositif infecté.","src":[{"id":"R-SSC-2021","loc":"Recommendation 27, Rationale","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le contrôle de la source se fait dès que c’est médicalement et logistiquement possible, après l’identification rapide d’un foyer qui l’exige.","type":"chirurgie"}],"objectif":"Le traitement vise à restaurer la perfusion des organes et à éliminer l’infection le plus vite possible."},"src":[{"id":"R-SSC-2021","loc":"Introduction ; Recommendations 1 à 58","lu_le":"2026-10-17"},{"id":"R-ERC-SPEC","loc":"Sepsis, définitions","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["urg-choc","urg-fievre-meninge"]},"traumatisme-facial":{"bloquant":false,"confirmation":"Le diagnostic repose sur le contexte traumatique et l’examen des rameaux.","exam":{"lignes":[{"mecanisme":"Une plaie de la joue peut sectionner un ou plusieurs rameaux du nerf après sa sortie du crâne.","nom":"Examen de la plaie et cotation rameau par rameau","pourquoi_ce_choix":"La conduite à tenir n’est pas encore sourcée par une ligne directrice suisse ou européenne lue. Ce point reste À vérifier dans une ligne directrice suisse ou européenne.","principe":"On teste chaque territoire du visage pour savoir quel rameau ne répond plus.","rang":1,"recherche":"Il recherche le ou les rameaux atteints et une plaie de la parotide.","statut":"À vérifier"},{"mecanisme":"La récupération dépend de la continuité du nerf et de la part des fibres qui ont dégénéré.","nom":"Électroneuromyographie (ENMG)","pourquoi_ce_choix":"Une activité volontaire conservée prouve la continuité du nerf, ce que l’examen clinique seul ne montre pas.","precautions":"Une baisse de l’amplitude motrice de plus de 80 à 90 % annonce un risque accru de récupération incomplète ; l’examen n’est informatif qu’après quelques jours.","principe":"On stimule le nerf au foramen stylo-mastoïdien et l’on mesure la réponse des muscles ; une baisse de l’amplitude traduit une perte axonale.","rang":2,"recherche":"Elle mesure la perte axonale et la continuité du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.3 Elektrophysiologische Diagnostik","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"traumatisme-facial","label":"Plaie ou traumatisme des rameaux du nerf facial","pec":{"mesures_generales":["Un avis ORL ou de chirurgie maxillo-faciale est demandé."],"moyens_specifiques":[{"limites":"Les limites et la récupération attendue restent À vérifier dans une source suisse ou européenne.","mecanisme":"Un rameau sectionné ne transmet plus la commande au muscle.","pourquoi_ce_choix":"Le choix entre suture et greffe, et le délai, restent À vérifier dans une source suisse ou européenne.","principe":"On rétablit la continuité du nerf.","statut":"À vérifier","texte":"Le nerf est suturé ou réparé par une greffe nerveuse.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à rétablir la continuité du nerf et à protéger l’œil."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.3","lu_le":"2026-10-17"}],"statut":"À vérifier","syn":["vii-site5-extracranien"]},"tumeur-cerebrale":{"bloquant":false,"confirmation":"Le diagnostic définitif repose sur l’examen histologique et moléculaire du tissu tumoral.","exam":{"lignes":[],"reference":{"mecanisme":"Une tumeur qui grandit dans le cerveau donne un déficit progressif selon son siège.","nom":"IRM cérébrale sans et avec gadolinium (T2, FLAIR, T1 3D avant et après injection)","pourquoi_ce_choix":"C’est l’examen de référence de la ligne directrice européenne ; il prépare aussi le prélèvement et la chirurgie.","precautions":"Les précautions du gadolinium (insuffisance rénale, grossesse) restent À vérifier dans une source suisse ou européenne.","principe":"Plusieurs séquences distinguent la tumeur du tissu sain, et le gadolinium montre les zones qui prennent le contraste.","recherche":"Elle détecte la tumeur, la situe et précise sa prise de contraste.","src":[{"id":"R-EANO-GLIO","loc":"Preoperative diagnostics ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé"}},"id":"tumeur-cerebrale","label":"Tumeur cérébrale","pec":{"mesures_generales":["Une décision de soins sans diagnostic tissulaire reste exceptionnelle."],"moyens_specifiques":[{"limites":"L’étendue de l’exérèse se limite quand la tumeur touche une zone fonctionnelle ; la suite du traitement dépend du type tumoral et reste hors de ce pilote.","mecanisme":"Le type exact de la tumeur, défini par l’histologie et la biologie moléculaire, décide du traitement.","pourquoi_ce_choix":"Une même intervention donne le diagnostic et traite ; une biopsie seule se réserve aux tumeurs qu’on ne peut pas enlever sans risque.","principe":"On prélève ou l’on enlève la tumeur pour obtenir le tissu et réduire la masse.","src":[{"id":"R-EANO-GLIO","loc":"Tissue acquisition ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une chirurgie première, à visée diagnostique et thérapeutique, est le plus souvent réalisée.","type":"chirurgie"}],"objectif":"Le traitement vise à obtenir un diagnostic tissulaire puis à traiter la tumeur selon son type."},"src":[{"id":"R-EANO-GLIO","loc":"Preoperative diagnostics ; Tissue acquisition","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site1-central"]},"tumeur-parotide":{"bloquant":false,"confirmation":"Le diagnostic est confirmé par la cytologie ou l’histologie ; une paralysie faciale avant l’opération est un facteur de mauvais pronostic.","exam":{"lignes":[{"mecanisme":"Une tumeur maligne de la parotide peut envahir le nerf facial, qui traverse la glande.","nom":"Palpation et échographie des parties molles de la face et du cou","pourquoi_ce_choix":"Elle est rapide, disponible chez l’ORL, et elle guide ensuite la cytoponction.","principe":"L’échographie montre la masse dans la glande et les ganglions du cou.","rang":1,"recherche":"Elles recherchent une masse parotidienne et des adénopathies.","src":[{"id":"R-DGN-BELL","loc":"§ 2.4 Bildgebung, dernier alinéa","lu_le":"2026-10-17"},{"id":"R-ESMO-SGC","loc":"Diagnostic work-up","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Une biopsie au trocart s’impose si la cytoponction ne permet pas de conclure.","mecanisme":"Seule l’étude des cellules distingue une tumeur maligne d’une tumeur bénigne.","nom":"Cytoponction à l’aiguille fine guidée par échographie","pourquoi_ce_choix":"C’est le prélèvement le moins invasif, et une confirmation cytologique ou histologique est obligatoire avant la chirurgie.","principe":"L’aiguille fine aspire des cellules, et le système de Milan classe le risque de malignité.","rang":2,"recherche":"Elle recherche des cellules malignes et classe le risque selon le système de Milan.","src":[{"id":"R-ESMO-SGC","loc":"Diagnostic work-up ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé"},{"alternative":"Un scanner avec injection la remplace si l’IRM est contre-indiquée.","mecanisme":"La tumeur peut s’étendre le long des nerfs et vers les ganglions.","nom":"IRM de la parotide et du cou","pourquoi_ce_choix":"C’est l’imagerie préférée quand une tumeur maligne est suspectée.","principe":"L’IRM montre les tissus mous en détail, dont l’extension le long des nerfs.","rang":3,"recherche":"Elle précise l’extension locale, le long des nerfs et vers les ganglions.","src":[{"id":"R-ESMO-SGC","loc":"Recommendations, imagerie","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"tumeur-parotide","label":"Tumeur maligne de la parotide","pec":{"mesures_generales":["Le patient est informé, avant l’opération, qu’une chirurgie plus étendue peut être nécessaire.","L’œil est protégé tant que la fermeture des paupières reste incomplète."],"moyens_specifiques":[{"limites":"La résection du nerf laisse une paralysie que seule une reconstruction peut améliorer ; les traitements complémentaires restent À vérifier dans la ligne directrice.","mecanisme":"La tumeur envahit le nerf ; une paralysie avant l’opération signale cette invasion et un moins bon pronostic.","pourquoi_ce_choix":"Une exérèse complète est le traitement de référence, et un nerf déjà paralysé ne garde pas de fonction à préserver.","principe":"On retire toute la glande avec la tumeur, et le nerf envahi avec elle.","src":[{"id":"R-ESMO-SGC","loc":"Surgical management of the primary ; Recommendations","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une parotidectomie totale est faite ; un nerf facial paralysé avant l’opération est réséqué puis reconstruit.","type":"chirurgie"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise une exérèse complète de la tumeur avec une prise en charge du nerf facial."},"src":[{"id":"R-ESMO-SGC","loc":"Diagnostic work-up ; Surgical management","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 3 Diagnostic différentiel","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site5-extracranien"]},"zona-oticus":{"bloquant":false,"confirmation":"Le diagnostic est clinique devant une paralysie faciale périphérique avec otalgie et vésicules auriculaires ; la sérologie le confirme.","exam":{"lignes":[{"mecanisme":"Le virus varicelle-zona réactivé atteint le nerf et la peau de son territoire sensitif, la conque et le conduit auditif.","nom":"Otoscopie et examen de la conque","pourquoi_ce_choix":"C’est un examen immédiat et sans risque qui change le traitement, car le zona impose un antiviral rapide.","precautions":"Une douleur très intense sans vésicule doit faire évoquer un zona sans éruption.","principe":"L’otoscopie montre les vésicules, même quand elles se limitent au conduit ou au tympan.","rang":1,"recherche":"Elle recherche des vésicules du conduit auditif externe, du tympan ou de la conque.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2 Examen clinique","lu_le":"2026-10-17"},{"id":"R-CEN-NC9","loc":"Nerf facial (VII), territoire sensitif","lu_le":"2026-10-17"}],"statut":"sourcé"},{"mecanisme":"L’infection virale peut atteindre les méninges.","nom":"Sérologie du virus varicelle-zona et ponction lombaire","pourquoi_ce_choix":"La ligne directrice les demande en cas de suspicion clinique ; ils confirment le diagnostic sans retarder l’antiviral.","principe":"La sérologie montre les anticorps contre le virus, et la ponction lombaire une inflammation du liquide cérébrospinal.","rang":2,"recherche":"Elles confirment l’infection par le virus varicelle-zona et recherchent une atteinte méningée.","src":[{"id":"R-DGN-BELL","loc":"§ 2.5 Laboruntersuchungen ; Tabelle 1","lu_le":"2026-10-17"}],"statut":"sourcé"}],"reference":null},"id":"zona-oticus","label":"Zona otique (syndrome de Ramsay-Hunt)","pec":{"mesures_generales":["L’antiviral débute sans attendre le résultat des examens.","L’œil est protégé et l’audition est surveillée."],"moyens_specifiques":[{"dose_ref":"valaciclovir-po-adulte-zona","limites":"La dose s’adapte à la fonction rénale ; le bénéfice chiffré sur la récupération faciale n’apparaît pas dans les sources lues.","mecanisme":"Le virus varicelle-zona réactivé se multiplie et abîme le nerf ; le pronostic est moins bon que dans la paralysie de Bell.","pourquoi_ce_choix":"La ligne directrice allemande impose un antiviral rapide dans le zona otique, et le protocole des HUG retient le valaciclovir, qui se prend par la bouche.","principe":"Un antiviral freine la multiplication du virus pour limiter l’atteinte du nerf.","src":[{"id":"R-DGN-BELL","loc":"§ 2.6 Prognose ; § 3.1, alinéa sur le zona otique","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le valaciclovir est donné par voie orale, rapidement et systématiquement ; la posologie suit la ligne suisse liée.","type":"pharmaco"},{"dose_ref":"valaciclovir-po-adulte-zona-ir","limites":"Les paliers de clairance suivent l’information professionnelle suisse liée ; une dialyse impose un avis spécialisé, À vérifier.","mecanisme":"Une insuffisance rénale ralentit l’élimination du valaciclovir.","pourquoi_ce_choix":"Le même antiviral reste utilisable, ce qui évite de changer de molécule chez le patient insuffisant rénal.","principe":"On réduit la dose selon la clairance de la créatinine pour éviter l’accumulation.","src":[{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Le valaciclovir est donné à dose adaptée à la clairance de la créatinine, selon la ligne suisse liée.","type":"pharmaco"},{"limites":"La durée et les contre-indications du corticoïde restent À vérifier dans l’information professionnelle suisse.","mecanisme":"L’inflammation du nerf s’ajoute à l’infection virale.","pourquoi_ce_choix":"Le protocole des HUG associe les deux traitements, car chacun agit sur un mécanisme différent.","principe":"Le corticoïde freine l’inflammation pendant que l’antiviral agit sur le virus.","src":[{"id":"R-HUG-PFP","loc":"§ 5 Traitement","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"Une corticothérapie orale est associée à l’antiviral. La posologie n’est pas reproduite ici : elle reste À vérifier dans l’information professionnelle suisse.","type":"pharmaco"},{"limites":"Elles ne traitent pas la paralysie ; un œil rouge ou douloureux exige un avis ophtalmologique urgent.","mecanisme":"La paralysie de l’orbiculaire empêche la fermeture complète des paupières, et la sécrétion de larmes peut baisser : la cornée se dessèche et risque un ulcère.","pourquoi_ce_choix":"Ces mesures simples et sans danger préviennent une complication qui menace la vue ; une chirurgie des paupières ne se discute que si la paralysie persiste.","principe":"On garde la cornée humide le jour et couverte la nuit jusqu’au retour de la fermeture.","src":[{"id":"R-DGN-BELL","loc":"§ 2.2 Klinische Untersuchung ; § 3.2 Nicht medikamentöse Therapie ; Tabelle 4","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 5 Traitement ; § 6 Suivi","lu_le":"2026-10-17"}],"statut":"sourcé","texte":"L’œil est protégé : larmes artificielles et pommade le jour, verre de montre ou pansement occlusif la nuit.","type":"autre"}],"objectif":"Le traitement vise à limiter l’atteinte du nerf, dont la récupération est moins souvent complète que dans la paralysie de Bell."},"src":[{"id":"R-DGN-BELL","loc":"§ 2.1, 2.2, 2.5, 2.6, 3.1","lu_le":"2026-10-17"},{"id":"R-HUG-PFP","loc":"§ 2, 3, 5","lu_le":"2026-10-17"}],"statut":"sourcé","syn":["vii-site2-genicule"]}};
